import { inject, Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { Credito } from '../../../../models/credito.model';
import { UtilsService } from '../../../../services/utils.service';

/**
 * Interfaz para el Segmento DE (Detalle de Crédito) del archivo de reporte a Buró de Crédito.
 * Este segmento reporta el monto y comportamiento de pago del crédito.
 * Debe aparecer al menos una vez por cada crédito reportado en el segmento CR (vigente y/o vencido).
 *
 * Documentación: Manual Técnico Entrega BD PM_B.pdf (Septiembre 2024)
 * - Sección: Segmento Detalle del Crédito - DE
 * - Longitud total del segmento: 114 caracteres fijos
 */
export interface DetalleCreditoBuro {
    /**
     * DE: Identificador del segmento (posición 1-2).
     * Siempre debe ser 'DE' (2 caracteres).
     * Requerido.
     */
    identificadorSegmento: string; // 'DE' (2 caracteres)

    /**
     * RFC del Acreditado (posición 3-15).
     * RFC de la persona moral (13 caracteres incluyendo guión).
     * Requerido. Si el acreditado está en el extranjero y no se conoce,
     * debe llenarse con 13 espacios. Si se conoce, debe reportarse.
     * Formato: AAAA######XXX (12 caracteres + guión = 13 total).
     */
    rfc: string; // 13 caracteres

    /**
     * Número de Contrato (posición 16-40).
     * Debe coincidir exactamente con el número de contrato del segmento CR.
     * Requerido. Llenar con exactamente 25 caracteres.
     * Si el contrato es más corto, rellenar con espacios a la derecha.
     */
    numeroContrato: string; // 25 caracteres

    /**
     * Días de vencimiento (posición 41-43).
     * Número de días de atraso (0 a 999). Formato numérico de 3 dígitos.
     * Si está al corriente, usar '000'.
     */
    diasVencimiento: string; // 3 dígitos

    /**
     * Cantidad (Saldo) (posición 44-63).
     * Saldo total (capital + intereses) en centavos.
     * Formato: 20 dígitos numéricos, relleno con ceros a la izquierda.
     * Ej: $1,500.00 → 150000 centavos → '00000000000000150000'
     */
    cantidad: string; // 20 dígitos

    /**
     * Intereses (posición 64-83).
     * Monto de intereses acumulados en centavos.
     * Opcional. Si no aplica, llenar con 20 ceros.
     */
    intereses: string; // 20 dígitos

    /**
     * Filler (posición 84-136).
     * Campo reservado. Debe ser exactamente 53 espacios en blanco.
     */
    filler: string; // 53 espacios
}

@Injectable({
    providedIn: 'any'
})
export class BuroDetalleCreditoService extends BuroSuperService<DetalleCreditoBuro> {
    utilsCreditos = inject(UtilsService)

    map(credito: Credito): DetalleCreditoBuro {
        const estado_cuenta = credito.estado_cuenta!

        // 2. Número de contrato → usa numero_cuenta del crédito
        const numeroContrato = (credito.folio || '').padEnd(25, ' ');

        // 3. Días de vencimiento → asumimos que lo obtienes de algún lado
        // En sistemas reales, esto se calcula desde el estado_cuenta o el último pago
        // Aquí asumimos que existe un campo en Credito llamado: diasVencimiento
        // Si no existe, debes agregarlo o calcularlo desde abonos y fechas
        const vencidoDesde = new Date(estado_cuenta.vencido_desde!)
        const diasVencimiento = this.format(vencidoDesde.getDay().toString(), 13);

        // 4. Cantidad: Saldo total en centavos
        // Suponiendo que tienes un campo en Credito con el saldo insoluto en pesos
        // Si no existe, debes calcularlo o pedirlo desde el backend
        const saldoInsolutoPesos = estado_cuenta.saldo_vencido || 0;
        const cantidadCentavos = Math.round(saldoInsolutoPesos * 100);
        const cantidad = cantidadCentavos.toString()

        // Este cliente no cobro intereses moratorios por que son programas sin fines de lucro
        const interesesAcumuladosPesos = 0;
        const interesesCentavos = Math.round(interesesAcumuladosPesos * 100);
        const intereses = interesesCentavos.toString()

        // 6. Filler: 53 espacios
        const filler = ' '.repeat(53);

        return {
            identificadorSegmento: 'DE',
            rfc: this.utilsCreditos.rfcFromCredito(credito),
            numeroContrato,
            diasVencimiento,
            cantidad,
            intereses,
            filler
        };
    }

    mapDetalleCredito(detalle: DetalleCreditoBuro): string {
        //revise el manual y los ejemplos si lleva etiquetas antes de cada seccion
        let str = '';
        str += 'DE' + this.format(detalle.identificadorSegmento, 2);
        str += '00' + this.format(detalle.rfc, 13);
        str += '01' + this.format(detalle.numeroContrato, 25);
        str += '02' + this.format(detalle.diasVencimiento, 3);
        str += '03' + this.format(detalle.cantidad, 20, true);
        str += '04' + this.format(detalle.intereses, 20, true);
        str += '05' + this.format(detalle.filler, 53);
        return str;
    }
}