import { Component, EventEmitter, inject, OnInit, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { EncabezadoBuro } from '../services/buro.encabezado.service';
import { BuroUtilsService } from '../services/buro.utils.service';

@Component({
  selector: 'app-buro-encabezado',
  imports: [
    FormsModule,
  ],
  templateUrl: './buro-encabezado.component.html',
  styleUrl: './buro-encabezado.component.css'
})
export class BuroEncabezadoComponent implements OnInit {
  private buroUtils = inject(BuroUtilsService)

  encabezado: EncabezadoBuro = {
    identificadorSegmento: 'BNCPM',
    claveUsuario: 'B775',
    claveUsuarioAnterior: '0000',
    tipoUsuario: '008',
    tipoFormato: '1',
    fechaReporte: '', // Se inicializará en ngOnInit
    periodo: '', // Se inicializará en ngOnInit
    version: '05',
    nombreOtorgante: 'FONDOS BC',
    filler: ' '.repeat(52)
  };

  // Fecha auxiliar para el input month (formato YYYY-MM)
  fechaReporteDate: string | null = null;

  @Output() encabezadoConfirmado = new EventEmitter<EncabezadoBuro>()

  ngOnInit() {
    // Inicializar con el mes y año actual
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth() + 1;
    this.fechaReporteDate = `${year}-${month.toString().padStart(2, '0')}`;
    this.updateFechas();
  }

  // Sincroniza fechaReporte y periodo basándose en el mes seleccionado
  onFechaReporteChange() {
    this.updateFechas();
  }

  private updateFechas() {
    if (this.fechaReporteDate) {
      const parts = this.fechaReporteDate.split('-');
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10);

      // Calcular el último día del mes seleccionado en UTC para evitar problemas de zona horaria
      const lastDayOfMonth = new Date(Date.UTC(year, month, 0));

      // Formatear la fecha a DDMMYYYY manualmente
      const y = lastDayOfMonth.getUTCFullYear();
      const m = (lastDayOfMonth.getUTCMonth() + 1).toString().padStart(2, '0');
      const d = lastDayOfMonth.getUTCDate().toString().padStart(2, '0');

      // Actualizar las propiedades del encabezado
      this.encabezado.fechaReporte = `${d}${m}${y}`;
      this.encabezado.periodo = `${month.toString().padStart(2, '0')}${year}`;
    }
  }

  // Formatea automáticamente la clave de usuario (alfanumérico, 4 caracteres)
  onClaveUsuarioInput(event: Event) {
    const input = event.target as HTMLInputElement;
    input.value = input.value.replace(/[^a-zA-Z0-9]/g, '').slice(0, 4);
    this.encabezado.claveUsuario = input.value;
  }

  // Formatea el periodo (MMYYYY)
  onPeriodoInput(event: Event) {
    const input = event.target as HTMLInputElement;
    let value = input.value.replace(/[^0-9]/g, '').slice(0, 6);

    // Autocompletar mes si es válido
    if (value.length >= 2) {
      const mes = parseInt(value.substring(0, 2), 10);
      if (mes < 1 || mes > 12) {
        value = value[0] + value.substring(2); // Corrige si mes inválido
      }
    }

    input.value = value;
    this.encabezado.periodo = value;
  }

  // Validación del formulario
  isFormValid(): boolean {
    return !!(
      this.encabezado.claveUsuario &&
      this.encabezado.claveUsuario.length === 4 &&
      /^[a-zA-Z0-9]{4}$/.test(this.encabezado.claveUsuario) &&
      this.encabezado.fechaReporte &&
      this.encabezado.periodo &&
      this.encabezado.periodo.length === 6 &&
      this.encabezado.nombreOtorgante.trim().length > 0 &&
      this.encabezado.nombreOtorgante.length <= 50
    );
  }

  // Acción al hacer submit
  onSubmit() {
    this.encabezadoConfirmado.emit(this.encabezado)
    console.log(this.encabezado)
  }
}
