import { Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { RegistroBuroInforme } from './buro.reporte.financiero';

/**
 * Interfaz para el Segmento TS (Cierre de Archivo) del reporte a Buró de Crédito.
 * Este segmento indica el fin del archivo y debe aparecer solo una vez, al final.
 *
 * Contiene:
 * - Número de compañías reportadas (segmentos EM)
 * - Cantidad total de segmentos DE (Detalles de Crédito) incluidos
 * - Filler de 53 espacios
 *
 * Documentación: Manual Técnico Entrega BD PM_B.pdf (Septiembre 2024)
 */
export interface CierreBuro {
    /**
     * TS: Identificador del segmento. Siempre debe ser 'TS'.
     */
    identificadorSegmento: string; // 'TS'

    /**
     * 00 - Número de compañías
     * Cantidad total de segmentos EM (Compañías) reportados en el archivo.
     * Numérico, 7 dígitos, rellenado con ceros a la izquierda.
     * Ej: 1 → '0000001'
     */
    numeroCompanias: string; // 7 dígitos

    /** total de cantidad SALDO, total de saldos en numero con ceros a la izquierda
     */
    cantidadSegmentosDE: string; // 30 dígitos

    /**
     * 02 - Filler
     * Campo reservado. Debe llenarse con exactamente 53 espacios en blanco.
     */
    filler: string; // 53 espacios
}

@Injectable({
    providedIn: 'any'
})
export class BuroCierreService extends BuroSuperService<CierreBuro> {
    map(segmentos : RegistroBuroInforme[]): CierreBuro {
        return {
            identificadorSegmento: 'TS',
            numeroCompanias: segmentos.length.toString(),
            cantidadSegmentosDE: segmentos.reduce((acc,seg) => acc+ +seg.detalleCredito.cantidad, 0).toString(),
            filler: ''
        }
    }

    mapCierre(cierre: CierreBuro): string {
        let str = '';
        str += 'TS' + this.format(cierre.identificadorSegmento, 2);
        str += '00' + this.format(cierre.numeroCompanias, 7, true);
        str += '01' + this.format(cierre.cantidadSegmentosDE, 30, true);
        str += '02' + this.format(cierre.filler, 53);
        return str;
    }
}