import { Component, Input, SimpleChanges } from '@angular/core';
import { SesionadosFiltros } from '../sesionados.component';
import { SolicitudApoyo } from '../../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../../controllers/solicitud.apoyo.service';
import { ApoyosCartaInstruccionesService } from '../../../../services/documentosLegales/contratos/apoyos_carta_de_instruccion.service';
import { UtilsService } from '../../../../services/utils.service';
import { AdvancedSearchFilter } from '../../../../shared/tabla/tabla.component';
import { CurrencyPipe, NgClass } from '@angular/common';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { Usuario } from '../../../../models/usuario.model';
import { SolicitudApoyoModalidadCotizacionService } from '../../../../controllers/solicitud.apoyo.modalidad.cotizacion.service';
import { TablaLocalService } from '../../../../services/tabla-local.service';
import { SolicitudApoyoModalidad } from '../../../../models/solicitud.apoyo.modalidad';
import { FormsModule } from '@angular/forms';
import { GraphsViewComponent } from "../../informe-tabla-dinamica-local/graphs-view/graphs-view.component";

interface SesionadoApoyo {
  id: number;
  cliente: string;
  programa_apoyo: string;
  monto_autorizado: number;
  municipio: string;
  apoyo: SolicitudApoyo;
  modalidad: SolicitudApoyoModalidad,
  isHidden?: boolean;
}

@Component({
  selector: 'app-sesionados-apoyos',
  imports: [
    NgClass,
    CurrencyPipe,
    FormsModule,
    GraphsViewComponent
  ],
  templateUrl: './sesionados-apoyos.component.html',
  styleUrl: './sesionados-apoyos.component.css'
})
export class SesionadosApoyosComponent {
  @Input() filtros!: SesionadosFiltros
  sesion_id: number = 0;
  apoyos: SolicitudApoyo[] = []
  dataTabla: SesionadoApoyo[] = []
  search: string = ''
  municipios: string[] = []
  usuario?: Usuario

  isLoading = false;
  isLoadingVerificados = false;

  constructor(
    private apoyoController: SolicitudApoyoService,
    public cartaInstruccionService: ApoyosCartaInstruccionesService,
    public utils: UtilsService,
    public tablaLocal: TablaLocalService,
    public storage: LocalStorageService,
    public solicitudApoyoModalidadCotizacionController: SolicitudApoyoModalidadCotizacionService,
  ) { }

  ngOnInit() {
    this.usuario = this.storage.getUser()
  }

  async ngOnChanges(changes: SimpleChanges) {
    if (changes['filtros']) {
      this.sesion_id = this.filtros.sesion_id ?? 0
      await this.loadData()
      this.setDataTabla()
      this.setMunicipios()
    }
  }

  private setDataTabla() {
    this.dataTabla = this.apoyos.map(a => {
      return {
        id: a.id,
        cliente: this.utils.nombreClienteFromDatosPersonales(a.datos_personales),
        programa_apoyo: a.programas_apoyos?.nombre || '',
        monto_autorizado: this.totalApoyo(a),
        municipio: a.ciudad_negocio?.nombre.toUpperCase() || 'N/A',
        apoyo: a,
        modalidad: this.modalidadPorSesion(a)!
      }
    })
  }

  private setMunicipios() {
    const municipios = this.apoyos.map(c => c.sucursales?.nombre.toUpperCase()).filter(m => m !== undefined)
    this.municipios = Array.from(new Set(municipios));
  }

  private async loadData() {
    const busqueda_avanzada: AdvancedSearchFilter[] = []
    
    if (this.filtros.sesion_id) {
      busqueda_avanzada.push({
        relation: 'solicitudesApoyosModalidades',
        andConditionals: [
          ['sesion_id', '=', this.filtros.sesion_id],
        ],
        conditionals: [],
      })
    }
    if (this.filtros.fecha_inicio) {
      busqueda_avanzada.push({
        relation: 'solicitudesApoyosModalidades',
        andConditionals: [
          ['created_at', '>=', this.filtros.fecha_inicio]
        ],
        conditionals: [],
      })
    }
    if (this.filtros.fecha_fin) {
      busqueda_avanzada.push({
        relation: 'solicitudesApoyosModalidades',
        andConditionals: [
          ['created_at', '<=', this.filtros.fecha_fin]
        ],
        conditionals: [],
      })
    }
    this.apoyos = await this.apoyoController.all({
      programas_apoyo_id: this.filtros.programa_apoyo_id,
      deleted_at: null,
    }, [
      "solicitudesApoyosModalidades.solicitudesApoyosModalidadesCotizaciones.apoyosProveedores",
      "solicitudesApoyosModalidades.sesiones",
      "ciudadNegocio",
      "ciudadFiscal",
      "programasApoyos",
      "datosPersonales",
      'sucursales'
    ], { busqueda_avanzada: JSON.stringify(busqueda_avanzada) })
    console.log(this.apoyos)
  }

  public async descargarCartas() {
    this.isLoading = true
    await this.multiplesMachoteCartasInstrucciones(this.apoyos)
    this.isLoading = false
  }

  public async descargarCartasVerificadas() {
    this.isLoading = true
    await this.multiplesMachoteCartasInstrucciones(this.apoyos)
    this.isLoading = false
  }

  public async multiplesMachoteCartasInstrucciones(apoyos: SolicitudApoyo[]) {
    const docDefinitions: any[] = []
    for (const apoyo of apoyos) {
      const modalidadActual = this.modalidadPorSesion(apoyo)
      for (const cot of modalidadActual!.solicitudes_apoyos_modalidades_cotizaciones!) {
        docDefinitions.push(await this.cartaInstruccionService.machoteCartaInstrucciones(apoyo, cot, modalidadActual, true, this.usuario?.email == 'ascornejo@baja.gob.mx'))
      }
    }
    await this.cartaInstruccionService.generateAndDownloadMultiplePDFs(docDefinitions)
  }

  public modalidadPorSesion(solicitud: SolicitudApoyo | undefined) {
    return solicitud?.solicitudes_apoyos_modalidades?.find(mod => mod.sesion_id == this.filtros.sesion_id)
  }

  public async buscar() {
    this.search = this.search.trim();
    this.tablaLocal.generalSearch(this.dataTabla, this.search)
    const resultados = this.dataTabla.filter(r => !r.isHidden)
    if (resultados.length == 0) {
      await this.loadData()
      this.tablaLocal.generalSearch(this.dataTabla, this.search)
    }
  }

  totalApoyo(apoyo: SolicitudApoyo): number {
    const modalidad = this.modalidadPorSesion(apoyo)
    if (!modalidad) {
      console.error(this.filtros, this.sesion_id)
    }
    return modalidad?.solicitudes_apoyos_modalidades_cotizaciones?.reduce((acc, cot) => acc + +cot.monto, 0) ?? 0
  }

  totalMontos() {
    return this.apoyos.reduce((acc, apoyo) => acc + (this.totalModalidadActualFromSolicitudApoyo(apoyo) ?? 0), 0)
  }

  public totalModalidadActualFromSolicitudApoyo(solicitudApoyo: SolicitudApoyo | undefined) {
    const modalidadActual = this.modalidadPorSesion(solicitudApoyo)
    if (!modalidadActual?.solicitudes_apoyos_modalidades_cotizaciones) return;
    return modalidadActual.solicitudes_apoyos_modalidades_cotizaciones.reduce((acc, cot) => acc + +(cot.monto), 0)
  }

  totalapoyosMunicipio(municipio: string) {
    return this.apoyos.filter(c => c.sucursales?.nombre.toUpperCase() == municipio).length
  }

  totalMontosMunicipio(municipio: string) {
    return this.apoyos.filter(c => c.sucursales?.nombre.toUpperCase() == municipio)
      .reduce((acc, c) => acc + +(this.totalModalidadActualFromSolicitudApoyo(c) ?? 0), 0)
  }
}
