import { Injectable } from '@angular/core';
import { SolicitudApoyo } from '../../../../models/solicitud.apoyo';
import { Credito } from '../../../../models/credito.model';
import { UtilsService } from '../../../../services/utils.service';

@Injectable({
  providedIn: 'root'
})
export class HistoricoStatsService {

  constructor(
    private utils: UtilsService,
  ) { }

  totalMontoSolicitudesPorProgramaApoyo(apoyos:SolicitudApoyo[], programa: string, municipio?: string, genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO') {
    return apoyos.filter(c => c.programas_apoyos?.nombre.toUpperCase() == programa && (!municipio || c.sucursales?.nombre.toUpperCase() == municipio) && (c.datos_personales?.genero == genero || !genero))
      .reduce((acc, c) => acc + +this.utils.totalSolicitudApoyo(c), 0)
  }

  solicitudesPorProgramaApoyo(apoyos:SolicitudApoyo[], programa: string, municipio?: string, genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO') {
    return apoyos.filter(c => c.programas_apoyos?.nombre.toUpperCase() == programa && (!municipio || c.sucursales?.nombre.toUpperCase() == municipio) && (c.datos_personales?.genero == genero || !genero)).length
  }

  totalMontoSolicitudesPorProductoFinanciero(creditos: Credito[], producto: string, municipio?: string, genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO') {
    return creditos.filter(c => c.productos_financieros?.nombre.toUpperCase() == producto && (!municipio || c.sucursales?.nombre.toUpperCase() == municipio) && (c.datos_personales?.genero == genero || !genero))
      .reduce((acc, c) => acc + +(c.monto_autorizado ?? 0), 0)
  }

  solicitudesPorProductoFinanciero(creditos: Credito[], producto: string, municipio?: string, genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO') {
    return creditos.filter(c => c.productos_financieros?.nombre.toUpperCase() == producto && (!municipio || c.sucursales?.nombre.toUpperCase() == municipio) && (c.datos_personales?.genero == genero || !genero)).length
  }

  empleosGeneradosApoyos(apoyos: SolicitudApoyo[], tipo: 'GENERADOS' | 'CONSERVADOS') {
    if (tipo == 'CONSERVADOS') {
      return apoyos.reduce((acc, item) => {
        return acc + item.empleos_generados_h + item.empleos_generados_m + item.empleos_generados_nb
      }, 0)
    }
    return apoyos.reduce((acc, item) => {
      return acc + item.empleos_a_generar_h + item.empleos_a_generar_m + item.empleos_a_generar_nb
    }, 0)
  }

  empleosGeneradosCreditos(creditos: Credito[], tipo: 'GENERADOS' | 'CONSERVADOS') {
    if (tipo == 'CONSERVADOS') {
      return creditos.reduce((acc, item) => {
        const pf = item.datos_persona_fisica?.negocios
        const pm = item.datos_personas_morales
        return acc +
          (pf ? pf.empleos_imss_hombres + pf.empleos_imss_mujeres + pf.empleos_imss_no_binarios + pf.empleos_informales_hombres + pf.empleos_informales_mujeres + pf.empleos_informales_no_binarios
            : (pm?.empleos_imss_hombres ?? 0) + (pm?.empleos_imss_mujeres ?? 0) + (pm?.empleos_imss_no_binarios ?? 0) + (pm?.empleos_informales_hombres ?? 0) + (pm?.empleos_informales_mujeres ?? 0) + (pm?.empleos_informales_no_binarios ?? 0))
      }, 0)
    }
    return creditos.reduce((acc, item) => {
      const pf = item.datos_persona_fisica?.negocios
      const pm = item.datos_personas_morales
      return acc + (pf ? pf.empleos_a_generar_hombres + pf.empleos_a_generar_mujeres + pf.empleos_a_generar_no_binarios : (pm?.empleos_a_generar_hombres ?? 0) + (pm?.empleos_a_generar_mujeres ?? 0) + (pm?.empleos_a_generar_no_binarios ?? 0))
    }, 0)
  }

  solicitudesGeneroPorMunicipio(creditos: Credito[], apoyos: SolicitudApoyo[], genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO', municipio?: string) {
    return this.creditosGeneroPorMunicipio(creditos, genero, municipio) | this.apoyosGeneroPorMunicipio(apoyos, genero, municipio)
  }

  solicitudesMunicipio(creditos: Credito[], apoyos: SolicitudApoyo[], municipio?: string) {
    return this.creditosPorMunicipio(creditos, municipio) + this.apoyosPorMunicipio(apoyos, municipio)
  }

  totalMontos(creditos: Credito[], apoyos: SolicitudApoyo[], municipio?: string) {
    return this.creditosTotalPorMunicipio(creditos, municipio) + this.apoyosTotalPorMunicipio(apoyos, municipio)
  }

  creditosGeneroPorMunicipio(creditos: Credito[], genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO', municipio?: string) {
    return creditos.filter(c => {
      const pf = c.datos_persona_fisica?.datos_personales
      const pm = c.datos_personas_morales?.representante_legal
      return ((pf ? pf.genero : pm?.genero) == genero) && c.sucursales?.nombre.toUpperCase() == municipio || !municipio
    }).length
  }

  creditosTotalPorMunicipio(creditos: Credito[], municipio?: string) {
    return creditos.filter(c => c.sucursales?.nombre.toUpperCase() == municipio || !municipio)
      .reduce((acc, cre) => acc + +(cre.monto_autorizado ?? 0), 0)
  }

  creditosPorMunicipio(creditos: Credito[], municipio?: string) {
    return creditos.filter(c => c.sucursales?.nombre.toUpperCase() == municipio || !municipio).length
  }

  apoyosGeneroPorMunicipio(apoyos: SolicitudApoyo[], genero?: 'HOMBRE' | 'MUJER' | 'NO BINARIO' | 'OTRO', municipio?: string) {
    return apoyos.filter(a => { a.datos_personales?.genero == genero && (a.sucursales?.nombre.toUpperCase() == municipio || !municipio) }).length
  }

  apoyosTotalPorMunicipio(apoyos: SolicitudApoyo[], municipio?: string) {
    return apoyos.filter(a => a.sucursales?.nombre.toUpperCase() == municipio || !municipio)
      .reduce((acc, apo) => acc + this.utils.totalSolicitudApoyo(apo), 0)
  }

  apoyosPorMunicipio(apoyos: SolicitudApoyo[], municipio?: string) {
    return apoyos.filter(a => a.sucursales?.nombre.toUpperCase() == municipio || !municipio).length
  }
}
