import {
  Component,
  Input,
  Output,
  EventEmitter,
  SimpleChanges,
} from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { Juridico } from '../../../../models/juridico.model';
import { JuridicoEtapaJudicial } from '../../../../models/juridico.etapa.judicial';

import { UtilsService } from '../../../../services/utils.service';
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';
import { TablaLocalService } from '../../../../services/tabla-local.service';
import { InformeTablaLocalComponent } from '../../shared/informe-tabla-local/informe-tabla-local.component';
import { UtilsEstadoCuentaService } from '../../../estado-cuenta/services/utils-estado-cuenta.service';
import { FormularioFlotanteComponent } from '../../../../shared/formulario-flotante/formulario-flotante.component';

interface CreditoAvanceJuridico {
  id: number;
  municipio: string;
  en_proceso_juridico: 'SI' | 'NO';
  demanda_ingresada: 'SI' | 'NO';
  demanda_por_presentar: 'SI' | 'NO';
  demanda_admitida: 'SI' | 'NO';
}

export interface CreditoAvanceStats {
  municipio: string;
  creditos_en_proceso_juridico: number;
  demandas_ingresadas: number;
  por_presentar: number;
  porc_creditos_demandados: string;
  demandas_admitidas: number;
  [key: string]: string | number;
}

@Component({
  selector: 'app-tabla-avance-judicial',
  imports: [InformeTablaLocalComponent, FormularioFlotanteComponent],
  templateUrl: './tabla-avance-judicial.component.html',
  styleUrl: './tabla-avance-judicial.component.css',
})
export class TablaAvanceJudicialComponent {
  @Input() creditos: Credito[] = [];
  @Input() fechaInicio: string = '';
  @Input() fechaFin: string = '';
  @Input() mesSeleccionado: string = "";
  @Output() dataTablaChange = new EventEmitter<CreditoAvanceStats[]>();

  dataSource: CreditoAvanceJuridico[] = [];

  show: boolean = false;
  rowExpanded?: CreditoAvanceStats;
  dataCreditos: any[] = [];
  

  columns: string[] = [];
  dataTabla: CreditoAvanceStats[] = [];

  constructor(
    private utils: UtilsService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    public excelGenerador: GeneradorExcelService,
    public tablaLocal: TablaLocalService,
  ) {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes['creditos']) {
      this.setDataSource();
      this.setDataTabla();
    }
  }

  private setDataSource() {
    this.dataSource = this.creditos
      .filter((c) => c.juridicos?.estado == "JUDICIAL")
      .map((credito) => {
        const juridicos = credito.juridicos!;
        const etapas = (juridicos?.juridicos_etapas_judiciales ?? []).filter(
          (e) => new Date(e.fecha ?? e.created_at) <= new Date(this.fechaFin),
        );
        const etapaActual = this.etapaJudicialActual(juridicos);
        return {
          id: credito.id,
          municipio: credito.sucursales?.nombre.trim().toUpperCase() || '',
          en_proceso_juridico: juridicos.estado == "JUDICIAL" ? 'SI' : 'NO',
          demanda_ingresada: this.yaPasoPorEtapaJudicial(
            etapas,
            'PRESENTACION DE LA DEMANDA',
          )
            ? 'SI'
            : 'NO',
          demanda_por_presentar: !this.yaPasoPorEtapaJudicial(
            etapas,
            'PRESENTACION DE LA DEMANDA',
          )
            ? 'SI'
            : 'NO',
          demanda_admitida: this.yaPasoPorEtapaJudicial(
            etapas,
            'ADMISION DE LA DEMANDA',
          )
            ? 'SI'
            : 'NO',
        };
      });
    console.log('data-source', this.dataSource);
  }

  private setDataTabla() {
    if (!this.dataSource.length) return;
    const municipios = Array.from(
      new Set(this.dataSource.map((r) => r.municipio.trim().toUpperCase())),
    );
    console.log(municipios);
    this.dataTabla = municipios.map((municipio) => {
      const creditos_en_proceso_juridico = this.dataSource.filter(
        (r) => r.en_proceso_juridico == 'SI' && r.municipio == municipio,
      ).length;
      const demandas_ingresadas = this.dataSource.filter(
        (r) => r.demanda_ingresada == 'SI' && r.municipio === municipio,
      ).length;
      const por_presentar = this.dataSource.filter(
        (r) => r.demanda_por_presentar == 'SI' && r.municipio === municipio,
      ).length;
      const demandas_admitidas = this.dataSource.filter(
        (r) => r.demanda_admitida == 'SI' && r.municipio === municipio,
      ).length;
      const porcentaje_demandados =
        creditos_en_proceso_juridico > 0
          ? (demandas_ingresadas / creditos_en_proceso_juridico) * 100
          : 0;

      return {
        municipio: municipio,
        creditos_en_proceso_juridico: creditos_en_proceso_juridico,
        demandas_ingresadas: demandas_ingresadas,
        por_presentar: por_presentar,
        porc_creditos_demandados: porcentaje_demandados.toFixed(2) + '%',
        demandas_admitidas: demandas_admitidas,
      };
    });
    this.dataTabla.push({
      municipio: 'Totales',
      creditos_en_proceso_juridico: this.tablaLocal.totales(
        this.dataTabla,
        'creditos_en_proceso_juridico',
      ),
      demandas_ingresadas: this.tablaLocal.totales(
        this.dataTabla,
        'demandas_ingresadas',
      ),
      por_presentar: this.tablaLocal.totales(this.dataTabla, 'por_presentar'),
      porc_creditos_demandados:
        (
          (this.tablaLocal.totales(this.dataTabla, 'demandas_ingresadas') /
            this.tablaLocal.totales(
              this.dataTabla,
              'creditos_en_proceso_juridico',
            )) *
          100
        ).toFixed(2) + '%',
      demandas_admitidas: this.tablaLocal.totales(
        this.dataTabla,
        'demandas_admitidas',
      ),
      juicios_desistidos: this.tablaLocal.totales(
        this.dataTabla,
        'juicios_desistidos',
      ),
    });
    this.columns = Object.keys(this.dataTabla[0] ?? {}) ?? [];

    // Emite los datos al padre
    this.dataTablaChange.emit(this.dataTabla);
  }

  yaPasoPorEtapaJudicial(etapas: JuridicoEtapaJudicial[], nombre: string) {
    return etapas.find(
      (e) => e.etapas_judiciales?.nombre.toUpperCase() == nombre,
    );
  }

  private etapaJudicialActual(juridico: Juridico | undefined) {
    const etapasOrdenadas = juridico?.juridicos_etapas_judiciales
      ?.filter(
        (e) => new Date(e.fecha ?? e.created_at) <= new Date(this.fechaFin),
      )
      .sort(
        (a, b) =>
          new Date(b.updated_at ?? '').getTime() -
          new Date(a.updated_at ?? '').getTime(),
      );
    const ultimaEtapaActiva = etapasOrdenadas?.[0];
    return ultimaEtapaActiva;
  }

  abrirVentanaFlotante(row: CreditoAvanceStats) {
    if (row.municipio == 'Totales') return;
    this.rowExpanded = row;
    this.dataCreditos = this.creditosFromMunicipio(row.municipio);
    this.show = true;
  }

  creditosFromMunicipio(municipio: string | undefined) {
    if (!municipio) return [];
    const creditos = this.creditos.filter(
      (c) =>
        c.sucursales?.nombre.toUpperCase() == municipio &&
        c.juridicos &&
        c.juridicos.estado == "JUDICIAL",
    );
    console.log(creditos);

    return creditos.map((credito) => {
      const pf = credito.datos_persona_fisica;
      const pm = credito.datos_personas_morales;
      const fechaFin = new Date(this.fechaFin);
      const estadoCuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(
        credito,
        false,
        this.fechaFin,
      );
      const ultimoAbono = estadoCuenta?.abonos_distribuidos?.at(-1)?.abono;
      const creditoDespacho = this.utils.despachoActualFromCredito(
        credito,
        fechaFin,
      );
      const juridico = credito.juridicos;
      const etapas = (juridico?.juridicos_etapas_judiciales ?? []).filter(
        (e) => new Date(e.fecha ?? e.created_at) <= new Date(this.fechaFin),
      );
      const etapaActual = this.etapaJudicialActual(juridico);
      const ultimaGestion = credito.credito_evento_cobros
        ?.filter(
          (e) =>
            e.fecha &&
            new Date(e.fecha) <= new Date(this.fechaFin) &&
            new Date(e.fecha) >= new Date(this.fechaInicio),
        )
        .at(-1);
      const convenio = credito.convenios
        ?.filter(
          (c) =>
            c.fecha_convenio &&
            new Date(c.fecha_convenio) <= new Date(this.fechaFin),
        )
        .find((c) => c.estatus == 'ACTIVO');

      return {
        'ID CREDITO': credito.id,
        'ID CLIENTE': this.utils.idClienteFromCredito(credito),
        'AÑO DE ORIGEN': this.utils.anioFromCredito(credito),
        'AÑO DE REESTRUCTURA': this.utils.esReestructura(credito.folio)
          ? this.utils.anioFromFecha(
              credito.fecha_reestructura ?? credito.liberado_fecha,
            )
          : null,
        FOLIO: credito.folio?.toUpperCase(),
        PROGRAMA: credito.productos_financieros?.nombre.toUpperCase(),
        'NOMBRE COMERCIAL': this.utils.nombreNegocioFromCredito(credito),
        'RAZÓN SOCIAL/NOMBRE PFA': this.utils.nombreClienteFromCredito(credito),
        'FECHA ASIGNACION AL DESPACHO': this.utils.fechaFormateada(creditoDespacho?.fecha_inicio) ?? "Sin asignar",
        'ASIGNACIÓN JURÍDICO': juridico?.estado,
        EXPEDIENTE: juridico?.expediente ?? 'NO REGISTRADO',
        PROCESO:
          etapaActual?.etapas_judiciales?.procesos_judiciales?.nombre.toUpperCase(),
        'ETAPA JUDICIAL': etapaActual?.etapas_judiciales?.nombre.toUpperCase(),
        'FECHA ÚLTIMO MOVIMIENTO ETAPA': this.utils.fechaFormateada(
          etapaActual?.fecha,
        ),
        'GESTIÓN DE COBRO': ultimaGestion ? 'REALIZADA' : 'NO REALIZADA',
        'RESULTADO ULTIMA GESTIÓN DE COBRO': ultimaGestion?.resultado,
        'FECHA ULTIMA GESTION DE COBRO': this.utils.fechaFormateada(
          ultimaGestion?.fecha,
        ),
        MUNICIPIO: credito.sucursales?.nombre.toUpperCase(),
        'ESTADO CONVENIO': convenio ? 'REALIZADO' : '',
        'TIPO CONVENIO': convenio?.tipo_convenio,
        'FECHA CONVENIO': this.utils.fechaFormateada(convenio?.fecha_convenio),
        'FECHA INICIO CONVENIO': this.utils.fechaFormateada(
          convenio?.fecha_inicio,
        ),
        'FECHA FIN CONVENIO': this.utils.fechaFormateada(
          convenio?.fecha_conclusion,
        ),
        'MONTO AUTORIZADO': this.parseToNumber(credito.monto_autorizado ?? 0),
        'CAPITAL MAS INTERÉS': this.parseToNumber(
          +(estadoCuenta?.interes_ordinario ?? 0) +
            +(credito.monto_autorizado ?? 0),
        ),
        'INTERES MORATORIO': this.parseToNumber(
          estadoCuenta?.interes_moratorio ?? 0,
        ),
        'MONTO RECUPERADO': this.parseToNumber(
          estadoCuenta?.monto_total_pagado ?? 0,
        ),
        'MONTO POR RECUPERAR': this.parseToNumber(
          estadoCuenta?.total_a_liquidar ?? 0,
        ),
        '% MONTO RECUPERADO':
          estadoCuenta?.total_a_liquidar == 0
            ? 100
            : (this.parseToNumber(estadoCuenta?.monto_total_pagado ?? 0) /
                this.parseToNumber(
                  estadoCuenta?.monto_total_mas_intereses ?? 1,
                )) *
              100,
        'MENSUALIDADES VENCIDAS': this.parseToNumber(
          estadoCuenta?.mensualidades_vencidas ?? 0,
        ),
        'MONTO VENCIDO': this.parseToNumber(estadoCuenta?.saldo_vencido ?? 0),
        '% MONTO VENCIDO':
          estadoCuenta?.total_a_liquidar == 0
            ? 0
            : this.parseToNumber(
                (estadoCuenta?.saldo_vencido ?? 0) /
                  this.parseToNumber(
                    estadoCuenta?.monto_total_mas_intereses ?? 1,
                  ),
              ) * 100,
        'MONTO ÚLTIMO ABONO': +(ultimoAbono?.monto ?? 0),
        'FECHA ÚLTIMO ABONO': ultimoAbono?.fecha.substring(0, 10),
        ESTATUS: estadoCuenta?.credito_status,
      };
    });
  }

  /**
   * Convierte un valor a número y aplica redondeo inteligente:
   * - Redondea hacia abajo si la diferencia es inferior a 0.10
   * - Redondea hacia arriba si la diferencia es 0.90 o superior
   * - Redondea normalmente para valores intermedios
   * @param value Valor a convertir (string o number)
   * @returns Número convertido y redondeado
   */
  parseToNumber(value: string | number): number {
    return +(+value.toString()).toFixed(2);
  }
}
