import { Component} from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { FormsModule } from '@angular/forms';
import { AdvancedSearchFilter } from '../../../shared/tabla/tabla.component';
import {
  CreditoAvanceStats,
  TablaAvanceJudicialComponent,
} from './tabla-avance-judicial/tabla-avance-judicial.component';
import {
  CreditoRecuperadoExtraJudicial,
  CreditoRecuperadoJudicial,
  TablaRecuperacionJudicialComponent,
} from './tabla-recuperacion-judicial/tabla-recuperacion-judicial.component';
import { UtilsEstadoCuentaService } from '../../estado-cuenta/services/utils-estado-cuenta.service';
import { GeneradorExcelService } from '../../reportes/services/generador-excel.service';
import { SelectorFechasPorMesComponent } from '../../../shared/selector-fechas-por-mes/selector-fechas-por-mes.component';
import { GestionesJudicialesComponent } from './gestiones-judiciales/gestiones-judiciales.component';
import { ConsolidadoJuridicoService } from './consolidado.juridico.service';

@Component({
  selector: 'app-informe-tabla-juridicos-despacho',
  imports: [
    FormsModule,
    TablaAvanceJudicialComponent,
    TablaRecuperacionJudicialComponent,
    SelectorFechasPorMesComponent,
    GestionesJudicialesComponent,
  ],
  templateUrl: './informe-tabla-juridicos-despacho.component.html',
  styleUrl: './informe-tabla-juridicos-despacho.component.css',
})
export class InformeTablaJuridicosDespachoComponent {
  isLoadingConsolidado = false;
  isDisabledDownloading = true; //Variable habilita el botón de descarga de datos a una hoja de cálculo.
  isDownloadingSheets = false; //Variable que habilita visualmente que se está descargando el archivo.

  progressConsolidado = 0;

  creditos: Credito[] = [];
  creditoAvanceDataTabla: CreditoAvanceStats[] = [];
  creditoJudicialDataTabla: CreditoRecuperadoJudicial[] = [];
  creditoExtraJudicialDataTabla: CreditoRecuperadoExtraJudicial[] = [];

  inicioConsolidado = new Date().toISOString().substring(0, 8) + '01';
  finConsolidado = new Date().toISOString().substring(0, 10);
  mes: string = '';

  constructor(
    private fetchDataService: ConsolidadoJuridicoService,
    public estadoCuentaUtils: UtilsEstadoCuentaService,
    public excelGenerator: GeneradorExcelService,
  ) {}

  public fetchData() {
    this.isLoadingConsolidado = true;
    this.progressConsolidado = 0;
    this.fetchDataConsolidado();
  }

  public downloadSheets() {
    this.isDisabledDownloading = true;
    this.isLoadingConsolidado = true;

    const judicialData = this.creditoJudicialDataTabla.map(d => {
      const { creditos, ...rest } = d;
      const creditos_ids = (creditos as Credito[])?.map(c => c.id).join(', ') || '';
      return { ...rest, creditos_ids };
    });

    const extraJudicialData = this.creditoExtraJudicialDataTabla.map(d => {
      const { creditos, ...rest } = d;
      const creditos_ids = (creditos as Credito[])?.map(c => c.id).join(', ') || '';
      return { ...rest, creditos_ids };
    });

    this.excelGenerator.exportToDataSheets(
      [
        [{ Tabla: 'Avance y recuperación jurídico' }],
        this.creditoAvanceDataTabla,
        [{ Tabla: 'Recuperación Judicial' }],
        judicialData,
        [{ Tabla: 'Recuperación Extra Judicial' }],
        extraJudicialData,
      ],
      `General-${this.mes}-recuperado`,
      'Informe general',
    );
    this.isLoadingConsolidado = false;
    this.isDisabledDownloading = false;
  }

  onDataTablaAvance(data: CreditoAvanceStats[]) {
    this.creditoAvanceDataTabla = data;
  }

  onDataTablaJudicial(data: CreditoRecuperadoJudicial[]) {
    this.creditoJudicialDataTabla = data;
  }

  onDataTablaExtraJudicial(data: CreditoRecuperadoExtraJudicial[]) {
    this.creditoExtraJudicialDataTabla = data;
  }

  private async fetchDataConsolidado() {
    const busqueda_avanzada: AdvancedSearchFilter[] = [
      {
        relation: 'juridicos',
        conditionals: [],
        andConditionals: [],
      },
    ];

    this.fetchDataService.progress$.subscribe((progress) => {
      this.progressConsolidado = progress;
    });

    this.creditos = await this.fetchDataService.fetchData({
      inicio: this.inicioConsolidado,
      fin: this.finConsolidado,
    });

    this.creditos.forEach(
      c => c.estado_cuenta = this.estadoCuentaUtils.calculateEstadoDeCuenta(c,false),
    );
    this.isLoadingConsolidado = false;
    this.isDisabledDownloading = false;
  }
}
