import { Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { Credito } from '../../../../models/credito.model';

export const CONSOLIDACIONES = {
    "ENSENADA": "00020012",
    "MEXICALI": "00020013",
    "TECATE": "00020014",
    "TIJUANA": "00020015",
    "PLAYAS DE ROSARITO": "00020016",
}

/**
 * Interfaz para el Segmento EM (Compañía) del archivo de reporte a Buró de Crédito.
 * Este segmento debe aparecer una sola vez por compañía reportada.
 * Aplica para Personas Morales.
 *
 * Documentación: Manual Técnico Entrega BD PM_B.pdf (Septiembre 2024)
 */
export interface CompaniaBuro {
    /**
     * EM: Identificador del segmento. Siempre debe ser 'EM'.
     */
    identificadorSegmento: string; // 'EM'

    /**
     * 00 - RFC del Acreditado
     * RFC de la persona moral (13 caracteres). Requerido.
     * Ejemplo: CAR9008215Z9
     */
    rfc: string; // 13 caracteres

    /**
     * 01 - CURP
     * Opcional. Solo para personas físicas. En personas morales, puede omitirse o llenarse con espacios.
     */
    curp: string; // 18 caracteres, opcional

    /**
     * 02 - Número DUM
     * No aplica para personas morales. Debe llenarse con ceros: '0000000000'
     */
    numeroDum: string; // 10 dígitos, '0000000000'

    /**
     * 03 - Nombre de la Compañía
     * Razón social completa de la persona moral. Requerido.
     */
    compania: string; // 150 caracteres

    /**
     * 04 - Nombre 1
     * No aplica para personas morales. Llenar con espacios.
     */
    nombre1: string; // 30 espacios

    /**
     * 05 - Nombre 2
     * No aplica. Llenar con espacios.
     */
    nombre2: string; // 30 espacios

    /**
     * 06 - Apellido Paterno
     * No aplica. Llenar con espacios.
     */
    apellidoPaterno: string; // 25 espacios

    /**
     * 07 - Apellido Materno
     * No aplica. Llenar con espacios.
     */
    apellidoMaterno: string; // 25 espacios

    /**
     * 08 - Nacionalidad
     * Código de nacionalidad (2 caracteres). Requerido.
     * Ej: 'MX' para mexicano.
     */
    nacionalidad: string; // 2 caracteres

    /**
     * 09 - Calificación de Cartera
     * Opcional. 2 caracteres. Si no aplica, espacios.
     */
    calificacionCartera: string; // 2 caracteres, opcional

    /**
     * 10 - Banxico 1
     * Clave principal asignada por Banxico (11 dígitos numéricos). Requerido.
     * Rellenar con ceros a la izquierda si es necesario.
     */
    banxico1: string; // 11 dígitos numéricos

    /**
     * 11 - Banxico 2
     * Clave secundaria. Opcional. Si no tiene, rellenar con ceros.
     */
    banxico2: string; // 11 dígitos, '00000000000'

    /**
     * 12 - Banxico 3
     * Clave terciaria. Opcional. Rellenar con ceros si no aplica.
     */
    banxico3: string; // 11 dígitos, '00000000000'

    /**
     * 13 - Dirección 1
     * Primera línea de la dirección. Requerido (40 caracteres).
     */
    direccion1: string; // 40 caracteres

    /**
     * 14 - Dirección 2
     * Segunda línea de dirección. Opcional. Rellenar con espacios si no aplica.
     */
    direccion2: string; // 40 caracteres

    /**
     * 15 - Colonia o Población
     * Nombre de la colonia o localidad. Requerido (60 caracteres).
     */
    colonia: string; // 60 caracteres

    /**
     * 16 - Delegación o Municipio
     * Nombre del municipio o delegación. Requerido (40 caracteres).
     */
    municipio: string; // 40 caracteres

    /**
     * 17 - Ciudad
     * Nombre de la ciudad. Requerido (40 caracteres).
     */
    ciudad: string; // 40 caracteres

    /**
     * 18 - Estado (México)
     * Clave de estado mexicano (4 caracteres). Ej: 'DF', 'GRO', 'NL'.
     */
    estado: string; // 4 caracteres

    /**
     * 19 - Código Postal
     * Código postal (10 caracteres). Requerido.
     */
    codigoPostal: string; // 10 caracteres

    /**
     * 20 - Teléfono
     * Número de teléfono (11 caracteres). Opcional. Rellenar con espacios si no aplica.
     */
    telefono: string; // 11 caracteres

    /**
     * 21 - Extensión
     * Extensión telefónica. Opcional (8 caracteres).
     */
    extension: string; // 8 caracteres

    /**
     * 22 - Fax
     * Número de fax. Opcional (11 caracteres).
     */
    fax: string; // 11 caracteres

    /**
     * 23 - Tipo de Cliente
     * 1 = Persona Moral
     * 2 = Persona Física con Actividad Empresarial
     * Para este caso: debe ser '1'
     */
    tipoCliente: string; // '1'

    /**
     * 24 - Estado en el extranjero
     * Solo si el domicilio está fuera de México. Opcional (40 caracteres).
     */
    estadoExtranjero: string; // 40 caracteres

    /**
     * 25 - País de origen del domicilio
     * Código ISO de 2 letras (ej: 'MX', 'US'). Opcional.
     */
    paisDomicilio: string; // 2 caracteres

    /**
     * 26 - Clave de consolidación
     * Usada para agrupar cuentas. Opcional (8 dígitos numéricos).
     * Si no aplica, rellenar con ceros.
     */
    claveConsolidacion: string; // 8 dígitos, ej. '00010006'

    /**
     * 27 - Filler
     * Campo reservado. Debe llenarse con 87 espacios en blanco.
     */
    filler: string; // 87 espacios
}

@Injectable({
    providedIn: 'any'
})
export class BuroCompaniaService extends BuroSuperService<CompaniaBuro> {
    map(credito: Credito): CompaniaBuro {
        const pf = credito.datos_persona_fisica?.datos_personales
        const pm = credito.datos_personas_morales
        const nombres= pf?.nombre.split(' ')??[]
        let primer_nombre = pf?.nombre
        let segundo_nombre =''
        if(nombres.length>1){
            primer_nombre = nombres[0]
            segundo_nombre = nombres[1]
        }

        const domicilio = this.utils.formatDomicilio(pf ?? pm)

        const telefono = pf ? pf.telefonos_personales?.at(0) : pm?.telefonos?.at(0)

        return {
            identificadorSegmento: 'EM',
            rfc: pf?.rfc ?? pm?.rfc ?? '',
            curp: pf?.curp ?? '',
            numeroDum: '0000000000',
            compania: pm?.razon_social ?? '',
            nombre1: primer_nombre ?? '',
            nombre2: segundo_nombre ?? '',
            apellidoPaterno: pf?.apellido_paterno ?? '',
            apellidoMaterno: pf?.apellido_materno ?? '',
            nacionalidad: "MX",
            calificacionCartera: '',
            banxico1: '9999999',
            banxico2: '9999999',
            banxico3: '9999999',
            direccion1: domicilio.linea1,
            direccion2: domicilio.linea2,
            colonia: pf?.colonia ?? pm ?.colonia ?? '',
            municipio: pf?.ciudades?.nombre ?? pm?.ciudades?.nombre ?? '',
            ciudad: '',
            estado: 'BCN',
            codigoPostal: pf?.codigo_postal ?? pm?.codigo_postal ?? '',
            telefono: telefono?.numero ?? '',
            extension: '',
            fax: '',
            tipoCliente: pm? '1' : '2' ,
            estadoExtranjero: '',
            paisDomicilio: '',
            claveConsolidacion: '',
            filler: ''
        }
    }

    mapCompania(compania: CompaniaBuro): string {
        let str = '';
        str += 'EM' + this.format(compania.identificadorSegmento, 2);
        str += '00' + this.format(compania.rfc, 13);
        str += '01' + this.format(compania.curp, 18);
        str += '02' + this.format(compania.numeroDum, 10);
        str += '03' + this.format(compania.compania, 150);
        str += '04' + this.format(compania.nombre1, 30);
        str += '05' + this.format(compania.nombre2, 30);
        str += '06' + this.format(compania.apellidoPaterno, 25);
        str += '07' + this.format(compania.apellidoMaterno, 25);
        str += '08' + this.format(compania.nacionalidad, 2);
        str += '09' + this.format(compania.calificacionCartera, 2);
        str += '10' + this.format(compania.banxico1, 11);
        str += '11' + this.format(compania.banxico2, 11);
        str += '12' + this.format(compania.banxico3, 11);
        str += '13' + this.format(compania.direccion1, 40);
        str += '14' + this.format(compania.direccion2, 40);
        str += '15' + this.format(compania.colonia, 60);
        str += '16' + this.format(compania.municipio, 40);
        str += '17' + this.format(compania.ciudad, 40);
        str += '18' + this.format(compania.estado, 4);
        str += '19' + this.format(compania.codigoPostal, 10, true);
        str += '20' + this.format(compania.telefono, 11);
        str += '21' + this.format(compania.extension, 8);
        str += '22' + this.format(compania.fax, 11);
        str += '23' + this.format(compania.tipoCliente, 1);
        str += '24' + this.format(compania.estadoExtranjero, 40);
        str += '25' + this.format(compania.paisDomicilio, 2);
        str += '26' + this.format(compania.claveConsolidacion, 8);
        str += '27' + this.format(compania.filler, 87);
        return str;
    }
}