import { Component, Input, SimpleChanges } from '@angular/core';
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';
import { FormsModule } from '@angular/forms';
import { TablaLocalService } from '../../../../services/tabla-local.service';

@Component({
  selector: 'app-informe-tabla-local',
  imports: [
    FormsModule,
  ],
  templateUrl: './informe-tabla-local.component.html',
  styleUrl: './informe-tabla-local.component.css'
})
export class InformeTablaLocalComponent {
  @Input() title:string=''
  @Input() dataSource:any[]=[]
  @Input() fileName:string='reporte_excel'
  dataFiltered:any[]=[]
  columns:string[]=[]
  ignoreColumns:string[]=[]
  @Input() containerClass:string='container-fluid'

  filtrado:Record<string,string> ={}

  constructor(
    public excelGenerador: GeneradorExcelService,  
    private tablaLocal:TablaLocalService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['dataSource']){
      this.setData()
    }
  }

  public filtrarDatos(){
    this.dataFiltered= this.tablaLocal.dataFiltered(this.dataSource, this.filtrado)
  }

  private setData(){
    this.dataFiltered= [...this.dataSource]
    if(!this.dataSource.length) return;
    this.columns= Object.keys(this.dataSource[0])
    this.columns = this.columns.filter(k => !this.ignoreColumns.includes(k))
  }
}
