import { Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { Credito } from '../../../../models/credito.model';

/**
 * Interfaz para el Segmento AC (Accionista) del archivo de reporte a Buró de Crédito.
 * Este segmento es requerido para Personas Morales cuando un accionista tiene una participación del 10% o más.
 * Debe incluirse una vez por cada accionista que cumpla con este criterio.
 *
 * Documentación: Manual Técnico Entrega BD PM_B.pdf (Septiembre 2024)
 */
export interface AccionistaBuro {
    /**
     * AC: Identificador del segmento. Siempre debe ser 'AC'.
     */
    identificadorSegmento: string; // 'AC'

    /**
     * 00 - RFC del Accionista
     * RFC del accionista (13 caracteres). Opcional.
     * Si no se conoce, puede omitirse (llenar con espacios).
     */
    rfc: string; // 13 caracteres, opcional

    /**
     * 01 - CURP del Accionista
     * Código ciudadano (18 caracteres). Opcional.
     */
    curp: string; // 18 caracteres, opcional

    /**
     * 02 - Número DUM
     * No aplica. Debe llenarse con ceros: '0000000000'
     */
    numeroDum: string; // 10 dígitos, '0000000000'

    /**
     * 03 - Nombre del Accionista (Persona Moral)
     * Si el accionista es una persona moral, se reporta aquí su razón social (150 caracteres). Requerido si aplica.
     */
    compania: string; // 150 caracteres

    /**
     * 04 - Nombre 1
     * No aplica para personas morales. Llenar con espacios.
     */
    nombre1: string; // 30 espacios

    /**
     * 05 - Nombre 2
     * No aplica. Llenar con espacios.
     */
    nombre2: string; // 30 espacios

    /**
     * 06 - Apellido Paterno
     * No aplica. Llenar con espacios.
     */
    apellidoPaterno: string; // 25 espacios

    /**
     * 07 - Apellido Materno
     * No aplica. Llenar con espacios.
     */
    apellidoMaterno: string; // 25 espacios

    /**
     * 08 - Porcentaje de participación
     * Porcentaje de participación accionaria (2 dígitos numéricos, 01 a 100).
     * Requerido. Ej: 55 para 55%.
     */
    porcentaje: string; // 2 dígitos numéricos

    /**
     * 09 - Dirección 1
     * Primera línea de la dirección del accionista. Opcional (40 caracteres).
     */
    direccion1: string; // 40 caracteres

    /**
     * 10 - Dirección 2
     * Segunda línea de dirección. Opcional (40 caracteres).
     */
    direccion2: string; // 40 caracteres

    /**
     * 11 - Colonia o Población
     * Nombre de la colonia o localidad. Opcional (60 caracteres).
     */
    colonia: string; // 60 caracteres

    /**
     * 12 - Delegación o Municipio
     * Municipio o delegación. Opcional (40 caracteres).
     * Nota: Si no se reporta Ciudad, este campo se vuelve requerido.
     */
    municipio: string; // 40 caracteres

    /**
     * 13 - Ciudad
     * Nombre de la ciudad. Opcional (40 caracteres).
     * Nota: Si no se reporta Municipio, este campo se vuelve requerido.
     */
    ciudad: string; // 40 caracteres

    /**
     * 14 - Estado (México)
     * Clave de estado mexicano (4 caracteres). Opcional.
     */
    estado: string; // 4 caracteres

    /**
     * 15 - Código Postal
     * Código postal (10 caracteres). Opcional.
     */
    codigoPostal: string; // 10 caracteres

    /**
     * 16 - Teléfono
     * Número de teléfono (11 caracteres). Opcional.
     */
    telefono: string; // 11 caracteres

    /**
     * 17 - Extensión
     * Extensión telefónica. Opcional (8 caracteres).
     */
    extension: string; // 8 caracteres

    /**
     * 18 - Fax
     * Número de fax. Opcional (11 caracteres).
     */
    fax: string; // 11 caracteres

    /**
     * 19 - Tipo de Cliente
     * 1 = Persona Moral
     * 2 = Persona Física con Actividad Empresarial
     * En este caso, depende de si el accionista es moral o físico.
     * Si es persona moral: '1'
     */
    tipoCliente: string; // '1' o '2'

    /**
     * 20 - Estado en el extranjero
     * Solo si el domicilio está fuera de México. Opcional (40 caracteres).
     * Requerido si el país no es MX.
     */
    estadoExtranjero: string; // 40 caracteres

    /**
     * 21 - País de origen del domicilio
     * Código ISO de 2 letras (ej: 'MX', 'US'). Opcional.
     * Si es extranjero, debe reportarse. Por defecto se asume 'MX'.
     */
    paisDomicilio: string; // 2 caracteres

    /**
     * 22 - Filler
     * Campo reservado. Debe llenarse con exactamente 40 espacios en blanco.
     */
    filler: string; // 40 espacios
}

@Injectable({
    providedIn: 'any'
})
export class BuroAccionistaService extends BuroSuperService<AccionistaBuro> {
    map(credito: Credito): AccionistaBuro[] {
        const accionistas = credito.datos_personas_morales?.accionistas ?? []
        return accionistas
        .filter(a => a.porcentaje_acciones>10 )
        .map(accionista => {
            const esMoral= this.utils.esPersonaMoral(accionista.rfc)
            const nombres = this.utils.separarNombreCompleto(accionista.nombre)

            return {
                identificadorSegmento: 'AC',
                rfc: accionista.rfc ?? '',
                curp: accionista.curp ?? '',
                numeroDum: '0000000000',
                compania: esMoral ?  accionista.nombre : '',
                nombre1: esMoral ? nombres.nombre : '',
                nombre2: esMoral ? nombres.nombre_adicional : '',
                apellidoPaterno: esMoral ? nombres.apellido_paterno : '',
                apellidoMaterno: esMoral ? nombres.apellido_materno : '',
                porcentaje: accionista.porcentaje_acciones.toString(),
                direccion1: '' ,
                direccion2: '',
                colonia: '',
                municipio: '',
                ciudad: '',
                estado: '',
                codigoPostal: '',
                telefono: accionista.telefono,
                extension: '',
                fax: '',
                tipoCliente: esMoral ? "1" : "2",
                estadoExtranjero: '',
                paisDomicilio: '',
                filler: ''
            }
        })
    }

    mapAccionista(accionista: AccionistaBuro): string {
        let str = '';
        str += 'AC' + this.format(accionista.identificadorSegmento, 2);
        str += '00' + this.format(accionista.rfc, 13);
        str += '01' + this.format(accionista.curp, 18);
        str += '02' + this.format(accionista.numeroDum, 10);
        str += '03' + this.format(accionista.compania, 150);
        str += '04' + this.format(accionista.nombre1, 30);
        str += '05' + this.format(accionista.nombre2, 30);
        str += '06' + this.format(accionista.apellidoPaterno, 25);
        str += '07' + this.format(accionista.apellidoMaterno, 25);
        str += '08' + this.format(accionista.porcentaje, 2);
        str += '09' + this.format(accionista.direccion1, 40);
        str += '10' + this.format(accionista.direccion2, 40);
        str += '11' + this.format(accionista.colonia, 60);
        str += '12' + this.format(accionista.municipio, 40);
        str += '13' + this.format(accionista.ciudad, 40);
        str += '14' + this.format(accionista.estado, 4);
        str += '15' + this.format(accionista.codigoPostal, 10);
        str += '16' + this.format(accionista.telefono, 11);
        str += '17' + this.format(accionista.extension, 8);
        str += '18' + this.format(accionista.fax, 11);
        str += '19' + this.format(accionista.tipoCliente, 1);
        str += '20' + this.format(accionista.estadoExtranjero, 40);
        str += '21' + this.format(accionista.paisDomicilio, 2);
        str += '22' + this.format(accionista.filler, 40);
        return str;
    }
}