import { Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { Credito } from '../../../../models/credito.model';

export interface AvalBuro {
    /**
     * AV: Identificador del segmento. Siempre debe ser 'AV'.
     */
    identificadorSegmento: string; // 2 chars, required

    /**
     * RFC del aval. Estructura según tipo: PM (12 chars), PFAE (13 chars). Homoclave requerida. Para extranjeros, opcional si país no es MX.
     */
    rfc: string; // 13 chars

    /**
     * Código de ciudadano (CURP en México). Opcional. Si no aplica, dejar en blanco.
     */
    curp: string; // 18 chars

    /**
     * Campo reservado. Debe ser '0000000000'.
     */
    numeroDum: string; // 10 chars

    /**
     * Nombre de la compañía (Persona Moral). Razón social como en acta constitutiva. Para PFAE, campo en blanco.
     */
    compania: string; // 150 chars

    /**
     * Primer nombre de Persona Física con Actividad Empresarial. Sin abreviaturas. Para PM, campo en blanco.
     */
    nombre1: string; // 30 chars

    /**
     * Segundo nombre de Persona Física. Si no aplica, campo en blanco.
     */
    nombre2: string; // 30 chars

    /**
     * Apellido paterno. Documentos oficiales. Si solo un apellido, reportar aquí y materno como 'NO PROPORCIONADO'.
     */
    apellidoPaterno: string; // 25 chars

    /**
     * Apellido materno. Si solo un apellido, reportar 'NO PROPORCIONADO'. Para PM, campo en blanco.
     */
    apellidoMaterno: string; // 25 chars

    /**
     * Primera línea de dirección. Incluye calle, número exterior/interior. Si no tiene número, 'SN' o 'DOMICILIO CONOCIDO SN'. Requerido.
     */
    direccion1: string; // 40 chars

    /**
     * Segunda línea de dirección (si es necesario). Si no aplica, campo en blanco.
     */
    direccion2: string; // 40 chars

    /**
     * Colonia o población. Si no aplica, campo en blanco.
     */
    colonia: string; // 60 chars

    /**
     * Alcaldía o municipio. Requerido si no se reporta ciudad o viceversa.
     */
    municipio: string; // 40 chars

    /**
     * Nombre de la ciudad. Requerido si no se reporta municipio o alcaldía.
     */
    ciudad: string; // 40 chars

    /**
     * Código de estado mexicano por defualt usar BCN
     */
    estado: string; // 4 chars

    /**
     * Código postal de 5 dígitos. Rellenar con espacios a la derecha para completar 10 caracteres. Para extranjero, '00000' o código correspondiente.
     */
    codigoPostal: string; // 10 chars

    /**
     * Número telefónico. Formato: código de área + hasta 8 dígitos. Longitud mínima 5. Sin guiones ni repetición de dígitos. Rellenar con espacios si es necesario.
     */
    telefono: string; // 11 chars

    /**
     * Extensión telefónica. Si no aplica, campo en blanco.
     */
    extension: string; // 8 chars

    /**
     * Número de fax. Formato similar a teléfono. Sin guiones ni repetición de dígitos. Rellenar con espacios si es necesario.
     */
    fax: string; // 11 chars

    /**
     * Tipo de aval: 1=Persona Moral, 2=Persona Física con Actividad Empresarial, 3=Fondo/Fideicomiso, 4=Gobierno, 5=PYME.
     */
    tipoCliente: string; // 1 char

    /**
     * Nombre del estado en país extranjero. Solo si domicilio fuera de México.
     */
    estadoExtranjero: string; // 40 chars

    /**
     * Código de país (ej: 'MX', 'US'). Por defecto 'MX' si no se reporta.
     */
    paisDomicilio: string; // 2 chars

    /**
     * Campo reservado. Llenar con 94 espacios en blanco.
     */
    filler: string; // 94 chars
}

@Injectable({
    providedIn: 'any'
})
export class BuroAvalService extends BuroSuperService<AvalBuro> {
    map(credito: Credito): AvalBuro {
        const aval = credito.aval;
        if (!aval) {
            // Si no hay aval, retornar estructura vacía
            return this.getEmptyAval();
        }

        // Separar el nombre completo del aval
        const nombreCompleto = this.utils.separarNombreCompleto(aval.nombre);

        // Formatear domicilio del aval
        const domicilio = this.utils.formatDomicilio({
            calle: aval.calle || '',
            no_exterior: aval.no_exterior,
            no_interior: aval.no_interior
        });

        // Determinar tipo de cliente basado en el RFC
        const esMoral = this.utils.esPersonaMoral(aval.rfc);
        const tipoCliente = esMoral ? '1' : '2'; // 1=Persona Moral, 2=Persona Física con Actividad Empresarial

        return {
            identificadorSegmento: 'AV',
            rfc: aval.rfc?.padEnd(13, ' ') || '',
            curp: aval.curp?.padEnd(18, ' ') || '',
            numeroDum: '0000000000',
            compania: esMoral ? aval.nombre.padEnd(150, ' ') : ''.padEnd(150, ' '),
            nombre1: !esMoral ? nombreCompleto.nombre.padEnd(30, ' ') : ''.padEnd(30, ' '),
            nombre2: !esMoral ? nombreCompleto.nombre_adicional.padEnd(30, ' ') : ''.padEnd(30, ' '),
            apellidoPaterno: !esMoral ? nombreCompleto.apellido_paterno.padEnd(25, ' ') : ''.padEnd(25, ' '),
            apellidoMaterno: !esMoral ? nombreCompleto.apellido_materno.padEnd(25, ' ') : ''.padEnd(25, ' '),
            direccion1: domicilio.linea1,
            direccion2: domicilio.linea2,
            colonia: aval.colonia?.padEnd(60, ' ') || '',
            municipio: aval.localidad?.padEnd(40, ' ') || '', // Usar localidad como municipio
            ciudad: '', // Campo requerido pero puede ir vacío si se tiene municipio
            estado: 'BCN', // Por defecto Baja California Norte
            codigoPostal: aval.codigo_postal?.padEnd(10, ' ') || '00000     ',
            telefono: '', // El aval no tiene teléfono en el modelo actual
            extension: '',
            fax: '',
            tipoCliente: tipoCliente,
            estadoExtranjero: '',
            paisDomicilio: 'MX',
            filler: ''.padEnd(94, ' ')
        };
    }

    private getEmptyAval(): AvalBuro {
        return {
            identificadorSegmento: 'AV',
            rfc: ''.padEnd(13, ' '),
            curp: ''.padEnd(18, ' '),
            numeroDum: '0000000000',
            compania: ''.padEnd(150, ' '),
            nombre1: ''.padEnd(30, ' '),
            nombre2: ''.padEnd(30, ' '),
            apellidoPaterno: ''.padEnd(25, ' '),
            apellidoMaterno: ''.padEnd(25, ' '),
            direccion1: ''.padEnd(40, ' '),
            direccion2: ''.padEnd(40, ' '),
            colonia: ''.padEnd(60, ' '),
            municipio: ''.padEnd(40, ' '),
            ciudad: ''.padEnd(40, ' '),
            estado: 'BCN',
            codigoPostal: '00000     ',
            telefono: ''.padEnd(11, ' '),
            extension: ''.padEnd(8, ' '),
            fax: ''.padEnd(11, ' '),
            tipoCliente: '2',
            estadoExtranjero: ''.padEnd(40, ' '),
            paisDomicilio: 'MX',
            filler: ''.padEnd(94, ' ')
        };
    }

    mapAval(aval: AvalBuro): string {
        let str = '';
        str += 'AV' + this.format(aval.identificadorSegmento, 2);
        str += '00' + this.format(aval.rfc, 13);
        str += '01' + this.format(aval.curp, 18);
        str += '02' + this.format(aval.numeroDum, 10);
        str += '03' + this.format(aval.compania, 150);
        str += '04' + this.format(aval.nombre1, 30);
        str += '05' + this.format(aval.nombre2, 30);
        str += '06' + this.format(aval.apellidoPaterno, 25);
        str += '07' + this.format(aval.apellidoMaterno, 25);
        str += '08' + this.format(aval.direccion1, 40);
        str += '09' + this.format(aval.direccion2, 40);
        str += '10' + this.format(aval.colonia, 60);
        str += '11' + this.format(aval.municipio, 40);
        str += '12' + this.format(aval.ciudad, 40);
        str += '13' + this.format(aval.estado, 4);
        str += '14' + this.format(aval.codigoPostal, 10, true); // true para rellenar con ceros
        str += '15' + this.format(aval.telefono, 11);
        str += '16' + this.format(aval.extension, 8);
        str += '17' + this.format(aval.fax, 11);
        str += '18' + this.format(aval.tipoCliente, 1);
        str += '19' + this.format(aval.estadoExtranjero, 40);
        str += '20' + this.format(aval.paisDomicilio, 2);
        str += '21' + this.format(aval.filler, 94);
        return str;
    }
}