import { inject, Injectable } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { BuroUtilsService } from './buro.utils.service';
import { RegistroBuroInforme } from './buro.reporte.financiero';

@Injectable({
    providedIn: 'any'
})
export abstract class BuroSuperService<T> {
    protected utils = inject(BuroUtilsService)
    
    abstract map(credito:Credito|RegistroBuroInforme[]): T|(T[]);

    /**
     * Función para formatear el output de texto de la base de datos.
     * Transforma: Todo a Mayúsculas, elimina carácteres (./)
     * @param value 
     * @param len 
     * @param number 
     * @returns 
     */
    protected format(value:string|null|undefined, len:number, number?:boolean){
        if(!value) return number? ''.padStart(len,'0') : ''.padEnd(len,' ')
        
        value = value
            .replace(/\//g, '') // Corrected escaping for forward slash
            .replace(/,/g, '')
            .replace(/\./g, '') // Corrected escaping for dot
            .replace(/'/g, '')
            .replace(/"/g, '') // Corrected escaping for double quote
            .replace(/`/g, '')
            .replace(/-/g, '')
            .replace(/\\/g, '') // Corrected escaping for backslash
            .normalize("NFD").replace(/[̀-ͯ]/g, "");

        return number? value.padStart(len, '0') : value.padEnd(len, ' ').substring(0,len).toUpperCase()
    }
}