import { Component, inject } from '@angular/core';
import { BuroEncabezadoComponent } from "./buro-encabezado/buro-encabezado.component";
import { Credito } from '../../../models/credito.model';
import { FilterOptions } from '../services/consolidado.super.service';
import { InformeCobranzaService } from '../services/informe-cobranza.service';
import { ProgressBarConsolidadoComponent } from "../shared/progress-bar-consolidado/progress-bar-consolidado.component";
import { DatesPickerComponent } from "../shared/dates-picker/dates-picker.component";
import { EncabezadoBuro } from './services/buro.encabezado.service';
import { BuroReporteFinancieroService } from './services/buro.reporte.financiero';
import { BuroReporteComercialService } from './services/buro.reporte.comercial';
import { InformeBuroService } from '../services/informe-buro.service';
import { GeneradorExcelService } from '../../reportes/services/generador-excel.service';

/**
 * Componente principal para generar reportes del Buró de Crédito
 *
 * Este componente permite generar y descargar reportes en formato de texto
 * para el Buró de Crédito de México, soportando tanto formato financiero
 * como comercial según las especificaciones técnicas.
 */
@Component({
  selector: 'app-buro-credito',
  imports: [
    BuroEncabezadoComponent,
    ProgressBarConsolidadoComponent,
    DatesPickerComponent
  ],
  templateUrl: './buro-credito.component.html',
  styleUrl: './buro-credito.component.css'
})
export class BuroCreditoComponent {
  /** Array de créditos a procesar para el reporte */
  dataSource: Credito[] = [];

  /** Opciones de filtrado para la consulta de datos */
  options: FilterOptions = {};

  /** Progreso de las operaciones asíncronas (0-100) */
  progress = 0;

  /** Indicador de estado de carga */
  isLoading = false;

  private informeBuroController = inject(InformeBuroService);
  private informeFinancieroBuro = inject(BuroReporteFinancieroService);
  private informeComercialBuro = inject(BuroReporteComercialService);
  private excel = inject(GeneradorExcelService)

  /**
   * Inicializa el componente y suscribe al observable de progreso
   */
  ngOnInit() {
    this.informeBuroController.progress$.subscribe(p => {
      this.progress = p;
    });
  }

  public async descargarExcel(){
    const data = await this.informeBuroController.fetchDataMaped(this.options)
    this.excel.exportToExcel(data, 'buro_credito_informe_excel')
  }

  /**
   * Obtiene los datos de créditos según las opciones de filtrado
   * Actualiza el dataSource con los resultados obtenidos
   */
  public async fetchData() {
    this.isLoading = true;
    this.dataSource = (await this.informeBuroController.fetchData(this.options));
    this.isLoading = false;
  }

  /**
   * Genera y descarga el informe del Buró de Crédito en formato .txt
   *
   * Determina el tipo de informe (financiero o comercial) basado en el
   * tipoFormato del encabezado y genera el archivo correspondiente.
   *
   * @param encabezado - Configuración del encabezado del reporte
   */
  public descargarInformeTxt(encabezado: EncabezadoBuro) {
    try {
      // Validar que haya datos para procesar
      if (!this.dataSource || this.dataSource.length === 0) {
        alert('No hay datos para generar el informe. Por favor, consulte los datos primero.');
        return;
      }

      // Determinar el tipo de informe según el tipoFormato
      const esFinanciero = encabezado.tipoFormato === '1';
      let contenidoInforme: string;

      if (esFinanciero) {
        // Generar informe financiero (formato detallado)
        contenidoInforme = this.informeFinancieroBuro.generarReporte(this.dataSource, encabezado);
      } else {
        // Generar informe comercial (formato sumarizado)
        contenidoInforme = this.informeComercialBuro.generarReporte(this.dataSource, encabezado);
      }

      console.log(contenidoInforme)

      // Crear y descargar el archivo
      this.descargarArchivo(contenidoInforme, encabezado, esFinanciero);

    } catch (error) {
      console.error('Error al generar el informe:', error);
      alert('Ocurrió un error al generar el informe. Por favor, revise la consola para más detalles.');
    }
  }

  /**
   * Crea y descarga un archivo .txt con el contenido del informe
   *
   * @param contenido - Contenido del informe a guardar
   * @param encabezado - Información del encabezado para el nombre del archivo
   * @param esFinanciero - Indica si es un informe financiero
   */
  private descargarArchivo(contenido: string, encabezado: EncabezadoBuro, esFinanciero: boolean) {
    // Generar nombre de archivo descriptivo
    const tipoInforme = esFinanciero ? 'FINANCIERO' : 'COMERCIAL';
    const fecha = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
    const nombreArchivo = `BC_${tipoInforme}_${encabezado.nombreOtorgante?.replace(/\s+/g, '_')}_${fecha}.txt`;

    // Crear blob con el contenido
    const blob = new Blob([contenido], { type: 'text/plain;charset=utf-8' });

    // Crear URL para descarga
    const url = URL.createObjectURL(blob);

    // Crear elemento de descarga
    const link = document.createElement('a');
    link.href = url;
    link.download = nombreArchivo;

    // Simular clic para descargar
    document.body.appendChild(link);
    link.click();

    // Limpiar
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    console.log(`Informe ${tipoInforme} generado: ${nombreArchivo}`);
    console.log(`Tamaño del archivo: ${contenido.length} caracteres`);
  }
}
