import { Component, Input, SimpleChanges } from '@angular/core';
import { SesionadosFiltros } from '../sesionados.component';
import { CreditoService } from '../../../../controllers/credito.service';
import { Credito } from '../../../../models/credito.model';
import { Conditional } from '../../../../controllers/super.service';
import { CurrencyPipe } from '@angular/common';
import { UtilsService } from '../../../../services/utils.service';
import { ContratoMachoteCartaInstruccionesService } from '../../../../services/documentosLegales/contratos/machote_de_Carta_de_instruccion.service';
import { Usuario } from '../../../../models/usuario.model';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { ProductoFinanciero } from '../../../../models/producto.financiero.model';
import { TablaLocalService } from '../../../../services/tabla-local.service';
import { FormsModule } from '@angular/forms';
import { GraphsViewComponent } from "../../informe-tabla-dinamica-local/graphs-view/graphs-view.component";

interface CreditoSesionado {
  id: number,
  cliente: string;
  producto_financiero: string;
  monto_autorizado: number;
  municipio: string;
  isHidden?: boolean;
  credito: Credito;
}

@Component({
    selector: 'app-sesionados-creditos',
    imports: [
    CurrencyPipe,
    FormsModule,
    GraphsViewComponent
],
    templateUrl: './sesionados-creditos.component.html',
    styleUrl: './sesionados-creditos.component.css'
})
export class SesionadosCreditosComponent {
  @Input() filtros!: SesionadosFiltros
  creditos: Credito[] = []
  dataTabla: CreditoSesionado[] = []
  productoFinanciero: ProductoFinanciero[] = []
  municipios: string[] = []
  usuario?: Usuario
  search: string = ''

  isLoading = false;
  isLoadingVerificados = false;

  constructor(
    public creditoController: CreditoService,
    public cartaInstruccionService: ContratoMachoteCartaInstruccionesService,
    public utils: UtilsService,
    public storage: LocalStorageService,
    public tablaLocal: TablaLocalService
  ) { }

  ngOnInit() {
    this.usuario = this.storage.getUser()
  }

  async ngOnChanges(changes: SimpleChanges) {
    if (changes['filtros']) {
      await this.loadData()
      this.setMunicipios()
    }
  }

  private setMunicipios() {
    const municipios = this.dataTabla.map(c => c.municipio.toUpperCase()).filter(m => m !== undefined)
    this.municipios = Array.from(new Set(municipios));
  }

  private async loadData() {
    const conditionals: Conditional[] = [
      {
        key: 'estado',
        operator: '=',
        value: 'ACTIVO',
      },
      {
        key: 'deleted_at',
        operator: 'IS NULL',
        value: 'null',
      },
    ]
    if (this.filtros.sesion_id) {
      conditionals.push({
        key: 'sesion_id',
        operator: '=',
        value: this.filtros.sesion_id
      })
    }
    if (this.filtros.fecha_inicio) {
      conditionals.push({
        key: 'dictaminado_fecha',
        operator: '>=',
        value: this.filtros.fecha_inicio
      })
    }
    if (this.filtros.fecha_fin) {
      conditionals.push({
        key: 'dictaminado_fecha',
        operator: '<=',
        value: this.filtros.fecha_fin
      })
    }
    if (this.filtros.producto_financiero_id) {
      conditionals.push({
        key: 'productos_financiero_id',
        operator: '=',
        value: this.filtros.producto_financiero_id
      })
    }
    this.creditos = await this.creditoController.all(conditionals, [
      'productosFinancieros',
      'datosPersonaFisica.datosPersonales',
      'datosPersonasMorales',
      'creditosPagos',
      'convenios.conveniosPagos',
      'sucursales',
      'datosPersonales',
      'datosPersonales.ciudades',
      'productosFinancieros',
      "inversionesProgramas.inversionTipos.inversionesTiposDetalles",
      'datosPersonasMorales.ciudades',
      'datosPersonaFisica.negocios',
      'datosPersonaFisica.negocios.ciudades',
      'sesiones',
    ])
    console.log(this.creditos)
    this.setDataTabla()
  }

  public async buscar() {
    this.search = this.search.trim();
    this.tablaLocal.generalSearch(this.dataTabla, this.search)
    const resultados = this.dataTabla.filter(r => !r.isHidden)
    if (resultados.length == 0) {
      await this.loadData()
      this.tablaLocal.generalSearch(this.dataTabla, this.search)
    }
  }

  private setDataTabla() {
    this.dataTabla = this.creditos.filter(c => c.productos_financieros?.nombre.toUpperCase() !== 'REESTRUCTURA').map(c => {
      const pf = c.datos_persona_fisica?.negocios
      const pm = c.datos_personas_morales
      const municipio = pm?.ciudades?.nombre ?? pf?.ciudades?.nombre
      return {
        id: c.id,
        cliente: this.utils.nombreClienteFromCredito(c),
        producto_financiero: c.productos_financieros?.nombre || '',
        monto_autorizado: +(c.monto_autorizado ?? 0),
        municipio: municipio?.toUpperCase() || 'N/A',
        credito: c,
      }
    })
  }

  public async descargarCartas() {
    this.isLoading = true
    const creditos = this.creditos.filter(c => c.productos_financieros?.nombre.toUpperCase() !== 'REESTRUCTURA')
    await this.cartaInstruccionService.multiplesMachoteCartasInstrucciones(creditos, this.usuario?.email == 'ascornejo@baja.gob.mx')
    this.isLoading = false
  }

  public async descargarCartasVerificadas() {
    this.isLoadingVerificados = true
    const creditos = this.creditos.filter(c => !!c.carta_instruccion_verificacion).filter(c => c.productos_financieros?.nombre.toUpperCase() !== 'REESTRUCTURA')
    await this.cartaInstruccionService.multiplesMachoteCartasInstrucciones(creditos, this.usuario?.email == 'ascornejo@baja.gob.mx')
    this.isLoadingVerificados = false
  }

  totalMontos() {
    return this.dataTabla.reduce((acc, c) => acc + +(c.monto_autorizado ?? 0), 0)
  }

  totalCreditosMunicipio(municipio: string) {
    return this.dataTabla.filter(c => c.municipio.toUpperCase() == municipio).length
  }

  totalMontosMunicipio(municipio: string) {
    return this.dataTabla.filter(c => c.municipio.toUpperCase() == municipio)
      .reduce((acc, c) => acc + +(c.monto_autorizado ?? 0), 0)
  }
}
