import { inject, Injectable } from '@angular/core';
import { BuroUtilsService } from './buro.utils.service';
import { Credito } from '../../../../models/credito.model';
import { BuroEncabezadoService, EncabezadoBuro } from './buro.encabezado.service';
import { BuroCompaniaService, CompaniaBuro } from './buro.compania.service';
import { AccionistaBuro, BuroAccionistaService } from './buro.accionista.service';
import { BuroCreditoService, CreditoBuro } from './buro.credito.service';
import { BuroDetalleCreditoService, DetalleCreditoBuro } from './buro.detalle.credito.service';
import { AvalBuro, BuroAvalService } from './buro.aval.service';
import { BuroCierreService } from './buro.cierre.service';

/**
 * Interfaz que representa un registro completo para el informe del Buró de Crédito
 *
 * Contiene todos los segmentos necesarios para reportar una operación crediticia
 * al Buró de Crédito de México, siguiendo el formato técnico establecido.
 */
export interface RegistroBuroInforme {
    /** Datos de la compañía (segmento EM) */
    datosCliente: CompaniaBuro;

    /** Información de accionistas (segmento AC) - array de accionistas */
    accionistas?: AccionistaBuro[];

    /** Datos del crédito (segmento CR) */
    credito: CreditoBuro;

    /** Detalle del crédito (segmento DE) */
    detalleCredito: DetalleCreditoBuro;

    /** Información de avalistas (segmento AV) */
    aveles?: AvalBuro;
}

/**
 * Servicio principal para generar reportes financieros para el Buró de Crédito
 *
 * Este servicio coordina la generación de reportes completos integrando todos los segmentos
 * necesarios según el formato requerido por el Buró de Crédito de México.
 *
 * @description
 * El flujo de generación de reportes sigue este orden:
 * 1. Encabezado (TL) - Información general del reporte
 * 2. Compañía (EM) - Datos de la empresa acreditada
 * 3. Accionistas (AC) - Información de accionistas con >10% participación
 * 4. Crédito (CR) - Datos generales del crédito
 * 5. Detalle Crédito (DE) - Información detallada del crédito
 * 6. Aveles (AV) - Información de los avalistas
 * 7. Cierre (TS) - Segmento final de control
 */
@Injectable({
    providedIn: 'any'
})
export class BuroReporteFinancieroService {
    private buroEncabezadoService = inject(BuroEncabezadoService);
    private buroCompaniaService = inject(BuroCompaniaService);
    private buroAccionistaService = inject(BuroAccionistaService);
    private buroCreditoService = inject(BuroCreditoService);
    private buroDetalleCreditoService = inject(BuroDetalleCreditoService);
    private buroAvalService = inject(BuroAvalService);
    private burroCierreService = inject(BuroCierreService);

    /**
     * Genera el reporte completo para el Buró de Crédito
     * @param creditos - Array de créditos a reportar
     * @param encabezado - Información del encabezado del reporte
     * @returns String con el reporte completo en formato de texto
     */
    generarReporte(creditos: Credito[], encabezado: EncabezadoBuro): string {
        const segmentos = this.mapCreditosToSegmentos(creditos);
        console.log(segmentos)
        let reporte = this.buroEncabezadoService.mapEncabezado(encabezado);

        // Mapear todos los segmentos en el orden correcto
        segmentos.forEach(segmento => {
            // Datos de la compañía (segmento EM)
            reporte += this.buroCompaniaService.mapCompania(segmento.datosCliente);

            // Accionistas si existen (segmento AC) - puede haber múltiples
            if (segmento.accionistas && segmento.accionistas.length > 0) {
                segmento.accionistas.forEach(accionista => {
                    reporte += this.buroAccionistaService.mapAccionista(accionista);
                });
            }

            // Créditos (segmento CR) - puede haber múltiples
            if (segmento.credito) {
                reporte += this.buroCreditoService.mapCredito(segmento.credito);
            }

            // Detalle del crédito (segmento DE)
            reporte += this.buroDetalleCreditoService.mapDetalleCredito(segmento.detalleCredito);

            // Aveles si existen (segmento AV)
            if (segmento.aveles) {
                reporte += this.buroAvalService.mapAval(segmento.aveles);
            }
        });

        // Agregar segmento de cierre (TS)
        const cierre = this.burroCierreService.map(segmentos);
        reporte += this.burroCierreService.mapCierre(cierre);

        return reporte;
    }

    /**
     * Convierte un array de créditos a un array de registros para el Buró de Crédito
     * @param creditos - Array de créditos a convertir
     * @returns Array de registros estructurados para el reporte del Buró de Crédito
     */
    mapCreditosToSegmentos(creditos: Credito[]): RegistroBuroInforme[] {
        return creditos.map(credito => {
            const accionistasArray = this.buroAccionistaService.map(credito);

            return {
                datosCliente: this.buroCompaniaService.map(credito),
                accionistas: accionistasArray.length > 0 ? accionistasArray : undefined,
                credito: this.buroCreditoService.map(credito),
                detalleCredito: this.buroDetalleCreditoService.map(credito),
                aveles:  credito.aval ? this.buroAvalService.map(credito) : undefined
            };
        });
    }
}