import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { CurrencyPipe, TitleCasePipe } from '@angular/common';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { UtilsService } from '../../../services/utils.service';
import { HistoricoStatsService } from '../historico/services/historico-stats.service';
import { ProgramaApoyo } from '../../../models/programa.apoyo';
import { GraphBar, GraphBarComponent } from '../../../shared/bar-chart/graph-bar/graph-bar.component';
import { BarChartComponent } from "../../../shared/bar-chart/bar-chart.component";
import { pipe } from 'rxjs';

interface Filtro{
  nombre:string;
  valoresBase:string[];
  filtroBase: () => number|string;
  filtroCruzado: () =>number|string;
  activado?:boolean;
}

interface Tabla {
  header: (TablaHeader)[][];
  body: TablaRow[][]
}

type TablaHeader = string | number | Header;

type TablaRow = string | number | null | Row;

interface Row {
  value: string | number | null
  style?: {
    td?: string;
    tr?: string;
  },
  pipe?: 'currency';
}

interface Header {
  colspan?: number;
  label: string;
  style?: {
    th?: string;
    tr?: string;
  }
}

@Component({
    selector: 'app-informe-ejercicio',
    imports: [
    CurrencyPipe,
    TitleCasePipe,
    BarChartComponent
],
    templateUrl: './informe-ejercicio.component.html',
    styleUrls: ['./informe-ejercicio.component.css']
})
export class InformeEjercicioComponent {
  @Input() creditos: Credito[] = []
  @Input() apoyos: SolicitudApoyo[] = []
  @Input() fechaInicio: string = ''
  @Input() fechaFin: string = ''
  productosFinancieros: string[] = []
  programasApoyos: string[] = []

  filtros = ['creditos', 'apoyos', 'productos_financieros']
  filtrosActivos: any = {
    creditos: true,
    productos_financieros: true,
    programas_apoyos: true,
    apoyos: true,
  }

  municipios: string[] = []

  dataTabla: Tabla = {
    header: [],
    body: [],
  }

  dataTablaPymes: GraphBar[] = []

  constructor(
    private utils: UtilsService,
    private stats: HistoricoStatsService,
  ) { }


  ngOnChanges(changes: SimpleChanges) {
    if (changes['creditos'] || changes['apoyos']) {
      this.setMunicipios()
      this.setProductosFinancieros()
      this.setProgramasApoyos()
      this.setDataTabla()
      this.setDataTablaPymes()
    }
  }

  private setDataTabla() {
    this.dataTabla.header = []
    this.dataTabla.body = []
    const totalesSecciones: string[] = []
    this.programasApoyos.forEach(p => totalesSecciones.push(...['Solicitudes', 'Monto', 'Mujeres', 'Hombres', 'Diversidad sexo genérica']))
    this.productosFinancieros.forEach(p => totalesSecciones.push(...['Solicitudes', 'Monto', 'Mujeres', 'Hombres', 'Diversidad sexo genérica']))
    this.dataTabla.header = [
      [
        { label: 'Localidad', style: { th: 'fw-bold' } },
        ...this.programasApoyos.map(p => ({ label: p, colspan: 5, style: { th: 'text-bg-danger' } })),
        ...this.productosFinancieros.map(p => ({ label: p, colspan: 5, style: { th: 'text-bg-danger' } })),
        {
          label: 'Apoyos',
          colspan: 5,
          style: { th: 'text-bg-success' }
        },
        {
          label: 'Creditos',
          colspan: 5,
          style: { th: 'text-bg-warning' }
        },
        {
          label: 'Total',
          colspan: 5,
          style: { th: 'text-bg-primary' }
        },
      ],
      [
        '',
      ]
    ]

    this.programasApoyos.forEach(p => {
      this.dataTabla.header[1].push(
        { label: 'Solicitudes', style: { th: 'text-bg-danger' } },
        { label: 'Monto', style: { th: 'text-bg-danger' } },
        { label: 'Mujeres', style: { th: 'text-bg-danger' } },
        { label: 'Hombres', style: { th: 'text-bg-danger' } },
        { label: 'Diversidad sexo genérica', style: { th: 'text-bg-danger' } }
      )
    })
    this.productosFinancieros.forEach(p => {
      this.dataTabla.header[1].push(
        { label: 'Solicitudes', style: { th: 'text-bg-danger' } },
        { label: 'Monto', style: { th: 'text-bg-danger' } },
        { label: 'Mujeres', style: { th: 'text-bg-danger' } },
        { label: 'Hombres', style: { th: 'text-bg-danger' } },
        { label: 'Diversidad sexo genérica', style: { th: 'text-bg-danger' } }
      )
    })

    this.dataTabla.header[1].push(
      { label: 'Solicitudes', style: { th: 'text-bg-success' } },
      { label: 'Monto', style: { th: 'text-bg-success' } },
      { label: 'Mujeres', style: { th: 'text-bg-success' } },
      { label: 'Hombres', style: { th: 'text-bg-success' } },
      { label: 'Diversidad sexo genérica', style: { th: 'text-bg-success' } },

      { label: 'Solicitudes', style: { th: 'text-bg-warning' } },
      { label: 'Monto', style: { th: 'text-bg-warning' } },
      { label: 'Mujeres', style: { th: 'text-bg-warning' } },
      { label: 'Hombres', style: { th: 'text-bg-warning' } },
      { label: 'Diversidad sexo genérica', style: { th: 'text-bg-warning' } },

      { label: 'Solicitudes', style: { th: 'text-bg-primary' } },
      { label: 'Monto', style: { th: 'text-bg-primary' } },
      { label: 'Mujeres', style: { th: 'text-bg-primary' } },
      { label: 'Hombres', style: { th: 'text-bg-primary' } },
      { label: 'Diversidad sexo genérica', style: { th: 'text-bg-primary' } },
    )

    const rows = []
    this.municipios.forEach(m => {
      const row: TablaRow[] = [m]
      this.programasApoyos.forEach(p => {
        row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, m))
        row.push({ value: this.stats.totalMontoSolicitudesPorProgramaApoyo(this.apoyos, p, m), pipe: 'currency' })
        row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, m, 'MUJER'))
        row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, m, 'HOMBRE'))
        row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, m, 'NO BINARIO') + this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, m, 'OTRO'))
      })

      this.productosFinancieros.forEach(p => {
        row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, m))
        row.push({ value: this.stats.totalMontoSolicitudesPorProductoFinanciero(this.creditos, p, m), pipe: 'currency' })
        row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, m, 'MUJER'))
        row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, m, 'HOMBRE'))
        row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, m, 'NO BINARIO') + this.stats.solicitudesPorProductoFinanciero(this.creditos, p, m, 'OTRO'))
      })

      row.push(this.stats.apoyosPorMunicipio(this.apoyos, m))
      row.push({ value: this.stats.apoyosTotalPorMunicipio(this.apoyos, m), pipe: 'currency' })
      row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'MUJER', m))
      row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'HOMBRE', m))
      row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'NO BINARIO', m) + this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'OTRO', m))

      row.push(this.stats.creditosPorMunicipio(this.creditos, m))
      row.push({ value: this.stats.creditosTotalPorMunicipio(this.creditos, m), pipe: 'currency' })
      row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'MUJER', m))
      row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'HOMBRE', m))
      row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'NO BINARIO', m) + this.stats.creditosGeneroPorMunicipio(this.creditos, 'OTRO', m))

      row.push(this.stats.solicitudesMunicipio(this.creditos, this.apoyos, m))
      row.push(this.stats.totalMontos(this.creditos, this.apoyos, m))
      row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'MUJER', m))
      row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'HOMBRE', m))
      row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'NO BINARIO', m) + this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'OTRO', m))
      rows.push(row)
    })

    const row: TablaRow[] = ['Total']
    this.programasApoyos.forEach(p => {
      row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p))
      row.push({ value: this.stats.totalMontoSolicitudesPorProgramaApoyo(this.apoyos, p), pipe: 'currency' })
      row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, 'MUJER'))
      row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, 'HOMBRE'))
      row.push(this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, 'NO BINARIO') + this.stats.solicitudesPorProgramaApoyo(this.apoyos, p, 'OTRO'))
    })

    this.productosFinancieros.forEach(p => {
      row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p))
      row.push({ value: this.stats.totalMontoSolicitudesPorProductoFinanciero(this.creditos, p), pipe: 'currency' })
      row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, 'MUJER'))
      row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, 'HOMBRE'))
      row.push(this.stats.solicitudesPorProductoFinanciero(this.creditos, p, 'NO BINARIO') + this.stats.solicitudesPorProductoFinanciero(this.creditos, p, 'OTRO'))
    })

    row.push(this.stats.apoyosPorMunicipio(this.apoyos))
    row.push({ value: this.stats.apoyosTotalPorMunicipio(this.apoyos), pipe: 'currency' })
    row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'MUJER'))
    row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'HOMBRE'))
    row.push(this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'NO BINARIO') + this.stats.apoyosGeneroPorMunicipio(this.apoyos, 'OTRO'))

    row.push(this.stats.creditosPorMunicipio(this.creditos))
    row.push({ value: this.stats.creditosTotalPorMunicipio(this.creditos), pipe: 'currency' })
    row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'MUJER'))
    row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'HOMBRE'))
    row.push(this.stats.creditosGeneroPorMunicipio(this.creditos, 'NO BINARIO') + this.stats.creditosGeneroPorMunicipio(this.creditos, 'OTRO'))

    row.push(this.stats.solicitudesMunicipio(this.creditos, this.apoyos))
    row.push({ value: this.stats.totalMontos(this.creditos, this.apoyos), pipe: 'currency' })
    row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'MUJER'))
    row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'HOMBRE'))
    row.push(this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'NO BINARIO') + this.stats.solicitudesGeneroPorMunicipio(this.creditos, this.apoyos, 'OTRO'))

    rows.push(row)

    this.dataTabla.body = rows;
  }

  private setDataTablaPymes() {
    this.dataTablaPymes = []
    this.municipios.forEach(m => {
      this.dataTablaPymes.push({
        label: m,
        value: this.stats.totalMontos(this.creditos, this.apoyos, m),
        pipe: 'currency',
      })
    })
  }

  private setProgramasApoyos() {
    this.programasApoyos = Array.from(new Set(this.apoyos.map(a => a.programas_apoyos?.nombre.toUpperCase()!)))
  }

  private setProductosFinancieros() {
    this.productosFinancieros = Array.from(new Set(this.creditos.map((c) => c.productos_financieros?.nombre.toUpperCase()!)))
    this.productosFinancieros = this.productosFinancieros.filter(pf => pf !== 'REESTRUCTURA')
  }

  private setMunicipios() {
    this.municipios = Array.from(new Set(this.creditos.map((c) => c.sucursales?.nombre.toUpperCase()!)))
  }

  public isHeader(tableHeader: TablaHeader): tableHeader is Header {
    return (tableHeader as Header).label !== undefined
  }

  public isRow(tableRow: TablaRow): tableRow is Row {
    return (tableRow as Row).value !== undefined
  }
}
