import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CreditoEventoCobro } from '../../../../models/credito.evento.cobro';
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';
import { UtilsService } from '../../../../services/utils.service';
import { InformeTablaLocalComponent } from "../../shared/informe-tabla-local/informe-tabla-local.component";

interface GestionJuridico{
  id:number;
  credito_id:number;
  fecha:string;
  modalidad:string;
  resultado:string;
  comentario:string;
  gestion_hecha_a:string;
  ejecutivo:string;
  registrado_en:string;
  [key: string]: string | number ;
}

@Component({
  selector: 'app-gestiones-judiciales',
  imports: [InformeTablaLocalComponent],
  templateUrl: './gestiones-judiciales.component.html',
  styleUrl: './gestiones-judiciales.component.css'
})
export class GestionesJudicialesComponent {
  @Input() creditos: Credito[] = []
  @Input() fechaInicio: string = '';
  @Input() fechaFin: string = '';
  @Input() estado:"EXTRAJUDICIAL" | "JUDICIAL" | "DEPURACIÓN DE SALDOS CONTABLES" = "JUDICIAL"
  dataTabla: GestionJuridico[]=[]
  columns:string[]=[]

  constructor(
    public excelGenerador: GeneradorExcelService,
    private utils: UtilsService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['creditos'] && this.creditos.length){
      console.log(this.creditos)
      this.setData()
    }
  }

  private setData(){
    const gestiones:CreditoEventoCobro[]=[]
    const inicio = new Date(this.fechaInicio.substring(0,10) +'T17:00:00Z')
    const fin = new Date(this.fechaFin.substring(0,10) +'T17:00:00Z')
    this.creditos
    .filter(c=> c.juridicos && c.juridicos?.estado==this.estado)
    .forEach(c => gestiones.push(...c.credito_evento_cobros??[]))

    this.dataTabla= gestiones
    .filter( g => {
      const fechaGestion= new Date(g.fecha?.substring(0,10) +'T17:00:00Z')
      return g.fecha && (fechaGestion <= fin && fechaGestion>= inicio)
    })
    .map(g => ({
      id:g.id,
      credito_id: g.credito_id,
      fecha: this.utils.fechaFormateada(g.fecha) ?? 'N/A',
      modalidad: g.modalidad,
      resultado:g.resultado,
      comentario:g.comentario,
      gestion_hecha_a:g.objetivo ||'No registrado',
      ejecutivo: g.nombre_usuario ?? g.usuario_ejecutivo?.nombre ?? 'No registrado',
      registrado_en: this.utils.fechaFormateada(g.created_at) ?? 'N/A'
    }))
    if(this.dataTabla.length){
      this.columns= Object.keys(this.dataTabla[0])
    }
    console.log(this.dataTabla, gestiones)
  }
}
