import { inject, Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';
import { Credito } from '../../../../models/credito.model';
import { UtilsService } from '../../../../services/utils.service';

/**
 * Interfaz para el Segmento CR (Crédito) del archivo de reporte a Buró de Crédito.
 * Este segmento contiene información general de la cuenta o crédito otorgado al acreditado.
 * Debe incluirse una vez por cada crédito a reportar (múltiple). Por cada accionista de mas 10% de participacion
 * 
 * Referencia: Manual Técnico Entrega BD PM_B V.5 (Septiembre 2024) - Sección "Segmento Cuenta o Crédito - CR" (página 56)
 */
export interface CreditoBuro {
    /**
     * CR: Identificador del segmento. 
     * Valor fijo: 'CR' (2 caracteres)
     */
    identificadorSegmento: string; // 'CR'

    /**
     * 00 - RFC del Acreditado
     * RFC de la persona moral (13 caracteres). Requerido.
     * Si el acreditado está en el extranjero y no se conoce, puede omitirse (llenar con espacios),
     * pero si se tiene, debe reportarse para integración de expedientes.
     * Campo llave: No debe modificarse en actualizaciones subsecuentes.
     */
    rfc: string; // 13 caracteres

    /**
     * 01 - Número de experiencias crediticias
     * Cantidad total de créditos activos e inactivos del acreditado con esta institución.
     * Numérico, 6 dígitos, rellenar con ceros a la izquierda.
     * Ejemplo: '000005'
     */
    numeroExperienciasCrediticias: string; // 6 dígitos

    /**
     * 02 - Número de contrato
     * Identificador único del crédito (25 caracteres). 
     * Requerido para formato financiero. 
     * Para formato comercial: No aplica (llenar con 25 espacios).
     * Campo llave: No debe modificarse en actualizaciones subsecuentes.
     */
    numeroContrato: string; // 25 caracteres

    /**
     * 03 - Número de contrato anterior
     * Identificador previo del crédito en caso de reestructuras (25 caracteres).
     * Si no aplica, llenar con 25 espacios.
     */
    numeroContratoAnterior: string; // 25 caracteres

    /**
     * 04 - Fecha de apertura
     * Fecha de otorgamiento del crédito (AAAAMMDD).
     * Si no aplica, llenar con '00000000'
     */
    fechaApertura: string; // 8 dígitos, ej. '20240115'

    /**
     * 05 - Plazo en meses
     * Duración total del crédito en meses (6 dígitos).
     * Si no aplica, '000000'
     */
    plazoMeses: string; // 6 dígitos

    /**
     * 06 - Tipo de crédito
     * Código que identifica el tipo de crédito (4 dígitos).
     * Catálogo de valores en Anexo 2 del manual.
     * Si no aplica, '0000'
     */
    tipoCredito: string; // 4 dígitos

    /**
     * 07 - Saldo inicial
     * Monto original del crédito en centavos (20 dígitos).
     * Si no aplica, '00000000000000000000'
     */
    saldoInicial: string; // 20 dígitos

    /**
     * 08 - Moneda
     * Código de moneda (3 dígitos). '001' = Pesos mexicanos.
     * Catálogo de valores en Anexo 2 del manual.
     * Requerido.
     */
    moneda: string; // '001'

    /**
     * 09 - Número de pagos
     * Cantidad total de pagos programados (4 dígitos).
     * Para créditos revolventes (incluyendo Crédito Simple y Crédito en Cuenta Corriente 1305),
     * reportar el número de pagos mínimos requeridos.
     * Si no aplica, '0000'
     */
    numeroPagos: string; // 4 dígitos

    /**
     * 10 - Frecuencia de pagos
     * Periodicidad de pagos en días (5 dígitos). 
     * Ejemplo: 00030 = mensual.
     * Si no aplica, '00000'
     */
    frecuenciaPagos: string; // 5 dígitos

    /**
     * 11 - Importe de pagos
     * Monto de cada pago programado en centavos (20 dígitos).
     * Si no aplica, ceros.
     */
    importePagos: string; // 20 dígitos

    /**
     * 12 - Fecha de último pago
     * Última fecha en que se recibió un pago (AAAAMMDD).
     * Si no aplica, '00000000'
     */
    fechaUltimoPago: string; // 8 dígitos

    /**
     * 13 - Fecha de reestructura
     * Fecha en que se reestructuró el crédito (AAAAMMDD).
     * Si no aplica, '00000000'
     */
    fechaReestructura: string; // 8 dígitos

    /**
     * 14 - Pago en efectivo
     * Monto total pagado en efectivo (centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    pagoEnEfectivo: string; // 20 dígitos

    /**
     * 15 - Fecha de liquidación
     * Fecha en que se liquidó totalmente el crédito (AAAAMMDD).
     * Si no aplica, '00000000'
     */
    fechaLiquidacion: string; // 8 dígitos

    /**
     * 16 - Quita
     * Monto condonado en una quita (centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    quita: string; // 20 dígitos

    /**
     * 17 - Dación en Pago
     * Monto cubierto por dación en pago (centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    dacionEnPago: string; // 20 dígitos

    /**
     * 18 - Quebranto o Castigo
     * Pérdida económica incurrida por el otorgante (centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    quebranto: string; // 20 dígitos

    /**
     * 19 - Clave de observación
     * Código que describe una situación especial del crédito (4 caracteres).
     * Catálogo de valores en Anexo 3 del manual.
     * Si no aplica, espacios.
     */
    claveObservacion: string; // 4 caracteres

    /**
     * 20 - Especiales
     * Indica si el crédito tiene características especiales (1 carácter).
     * Valores: 'S' = Sí, 'N' = No, ' ' = No aplica.
     */
    especiales: string; // 1 carácter

    /**
     * 21 - Fecha de primer incumplimiento
     * Primera fecha en que el acreditado dejó de pagar (AAAAMMDD).
     * Si no aplica, '00000000'
     */
    fechaPrimerIncumplimiento: string; // 8 dígitos

    /**
     * 22 - Saldo insoluto del principal
     * Saldo pendiente por pagar del capital (en centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    saldoInsoluto: string; // 20 dígitos

    /**
     * 23 - Crédito Máximo
     * Monto máximo autorizado en la línea de crédito (en centavos, 20 dígitos).
     * Si no aplica, ceros.
     */
    creditoMaximo: string; // 20 dígitos

    /**
     * 24 - Fecha de ingreso a cartera vencida
     * Fecha en que el crédito entró en mora (AAAAMMDD).
     * Campo agregado en versión 5.0.
     * Si no aplica, '00000000'
     */
    fechaCarteraVencida: string; // 8 dígitos

    /**
     * 25 - Filler
     * Campo reservado para uso futuro (40 espacios).
     * Debe llenarse con espacios en blanco.
     */
    filler: string; // 40 espacios

    /**
     * 26 - Tipo de Responsabilidad
     * Código que indica el tipo de responsabilidad del crédito (1 carácter).
     * Campo agregado en versión 5.0 (septiembre 2024).
     * Catálogo de valores definido por Buró de Crédito.
     * Si no aplica, espacio en blanco.
     */
    tipoResponsabilidad: string; // 1 carácter
}

@Injectable({
    providedIn: 'any'
})
export class BuroCreditoService extends BuroSuperService<CreditoBuro> {
    utilsCreditos = inject(UtilsService);
    map(credito: Credito): CreditoBuro {
        const rfc = this.utilsCreditos.rfcFromCredito(credito)!;
        const estadoCuenta = credito.estado_cuenta!;
        const segmentos: CreditoBuro[] = [];
        
        // Determinar si es reestructura
        const esReestructura = this.utilsCreditos.esReestructura(credito.folio);
        
        const saldoInsolutoCentavos = Math.ceil(estadoCuenta.saldo_vencido);
        // Calcular montos en centavos
        const saldoInicialCentavos = Math.ceil(estadoCuenta.monto_total_mas_intereses);
        const importePagosCentavos = estadoCuenta.periodo_vigente?.pago_programado_total 
        ? Math.ceil(estadoCuenta.periodo_vigente.pago_programado_total) 
        : saldoInsolutoCentavos;
        
        
        // Obtener fechas en formato AAAAMMDD
        const fechaApertura = this.utils.formatDateToDDMMYYYY(credito.fecha_convenio);
        const fechaUltimoPago = estadoCuenta.abonos_distribuidos?.length 
            ? this.utils.formatDateToDDMMYYYY(estadoCuenta.abonos_distribuidos.at(-1)!.abono.fecha)
            : '00000000';
        const fechaReestructura = credito.fecha_reestructura 
            ? this.utils.formatDateToDDMMYYYY(credito.fecha_reestructura)
            : '00000000';
        const fechaPrimerIncumplimiento = estadoCuenta.vencido_desde
            ? this.utils.formatDateToDDMMYYYY(estadoCuenta.vencido_desde)
            : '00000000';
        const fechaCarteraVencida = estadoCuenta.vencido_desde
            ? this.utils.formatDateToDDMMYYYY(estadoCuenta.vencido_desde)
            : '00000000';
        
        // Determinar clave de observación
        let claveObservacion = '    '; // 4 espacios por defecto
        if (esReestructura) claveObservacion = 'RA'; // Reestructurado
        if (estadoCuenta.saldo_vencido > 0) claveObservacion = 'LG'; // Crédito garantizado
        if(estadoCuenta.total_a_liquidar<=0) claveObservacion = 'CC'

        
        
        // Crear segmento CR
        return {
            identificadorSegmento: 'CR',
            rfc: rfc.padEnd(13, ' '),
            numeroExperienciasCrediticias: '000000', // Valor por defecto - ajustar según lógica de negocio
            numeroContrato: credito.id.toString().padEnd(25, ' '),
            numeroContratoAnterior: this.utils.folioAnterior(credito).padEnd(25, ' '),
            fechaApertura,
            plazoMeses: estadoCuenta.periodos.length.toString().padStart(6, '0'),
            tipoCredito: esReestructura ? '1323' : '6292',
            saldoInicial: saldoInicialCentavos.toString().padStart(20, '0'),
            moneda: '001',
            numeroPagos: estadoCuenta.periodos.length.toString().padStart(4, '0'),
            frecuenciaPagos: '00030', // 30 días = mensual
            importePagos: importePagosCentavos.toString().padStart(20, '0'),
            fechaUltimoPago,
            fechaReestructura,
            pagoEnEfectivo: '0'.padStart(20, '0'), // Calcular si aplica
            fechaLiquidacion: '00000000', // Calcular si aplica
            quita: '0'.padStart(20, '0'), // Calcular si aplica
            dacionEnPago: '0'.padStart(20, '0'), // Calcular si aplica
            quebranto: '0'.padStart(20, '0'), // Calcular si aplica
            claveObservacion,
            especiales: 'N', // 'N' por defecto
            fechaPrimerIncumplimiento,
            saldoInsoluto: saldoInsolutoCentavos.toString().padStart(20, '0'),
            creditoMaximo: '0'.padStart(20, '0'), // Calcular si aplica
            fechaCarteraVencida,
            filler: ''.padEnd(40, ' '),
            tipoResponsabilidad: ' ' // Agregado: campo requerido, espacio en blanco por defecto
        }
    }

    mapCredito(credito: CreditoBuro): string {
        let str = '';
        str += 'CR' + this.format(credito.identificadorSegmento, 2);
        str += '00' + this.format(credito.rfc, 13);
        str += '01' + this.format(credito.numeroExperienciasCrediticias, 6, true);
        str += '02' + this.format(credito.numeroContrato, 25);
        str += '03' + this.format(credito.numeroContratoAnterior, 25);
        str += '04' + this.format(credito.fechaApertura, 8);
        str += '05' + this.format(credito.plazoMeses, 6, true);
        str += '06' + this.format(credito.tipoCredito, 4);
        str += '07' + this.format(credito.saldoInicial, 20, true);
        str += '08' + this.format(credito.moneda, 3);
        str += '09' + this.format(credito.numeroPagos, 4, true);
        str += '10' + this.format(credito.frecuenciaPagos, 5, true);
        str += '11' + this.format(credito.importePagos, 20, true);
        str += '12' + this.format(credito.fechaUltimoPago, 8);
        str += '13' + this.format(credito.fechaReestructura, 8);
        str += '14' + this.format(credito.pagoEnEfectivo, 20, true);
        str += '15' + this.format(credito.fechaLiquidacion, 8);
        str += '16' + this.format(credito.quita, 20, true);
        str += '17' + this.format(credito.dacionEnPago, 20, true);
        str += '18' + this.format(credito.quebranto, 20, true);
        str += '19' + this.format(credito.claveObservacion, 4);
        str += '20' + this.format(credito.especiales, 1);
        str += '21' + this.format(credito.fechaPrimerIncumplimiento, 8);
        str += '22' + this.format(credito.saldoInsoluto, 20, true);
        str += '23' + this.format(credito.creditoMaximo, 20, true);
        str += '24' + this.format(credito.fechaCarteraVencida, 8);
        str += '25' + this.format(credito.filler, 40);
        str += '26' + this.format(credito.tipoResponsabilidad, 1); // Agregado: campo 26 - Tipo de Responsabilidad
        return str;
    }
}