import { Injectable } from "@angular/core";
import { InformeCobranzaService } from "./informe-cobranza.service";
import { FilterOptions } from "./consolidado.super.service";
import { Credito } from "../../../models/credito.model";

@Injectable({
    providedIn: 'root'
})
export class InformeBuroService extends InformeCobranzaService {
    
    public override filter = (c: Credito, options?: FilterOptions) => {
        const estadoCuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(c, false, options?.fecha_fin)

        if(!estadoCuenta){
            return false;
        }

        if (!c.creditos_pagos?.length) {
            return false
        }
        if (!options) {
            return true
        }

        // 1. Filtrar por producto financiero
        if (options.producto_financiero_id && c.productos_financiero_id != options.producto_financiero_id) {
            return false;
        }

        // 2. Verificar si el crédito tiene saldo pendiente o está liquidado en el mes actual
        const tieneSaldoPendiente = (estadoCuenta?.total_a_liquidar ?? 0) > 0;
        const estaLiquidado = (estadoCuenta?.total_a_liquidar ?? 0) <= 0;

        // Si no tiene saldo pendiente, verificar si fue liquidado en el mes actual
        if (!tieneSaldoPendiente && estaLiquidado) {
            const fueLiquidadoEnMesActual = this.verificarLiquidadoEnMesActual(c, options);
            if (!fueLiquidadoEnMesActual) {
                return false;
            }
        }

        // 3. Calcular la fecha de última actividad
        const fechaUltimaActividad = this.calcularFechaUltimaActividad(c, estadoCuenta);

        // 4. Verificar que la última actividad tenga 72 meses o menos de antigüedad
        if (!this.verificarActividadReciente(fechaUltimaActividad)) {
            return false;
        }

        // 5. Si no hay fechas para filtrar, retorna true
        if (!options.fecha_inicio && !options.fecha_fin) {
            return true;
        }

        // 6. Filtrar por fecha de inicio (sin problemas de zona horaria)
        if (options.fecha_inicio) {
            const inicioDate = new Date(options.fecha_inicio);
            // Establecer al inicio del día (00:00:00) en la zona horaria local
            inicioDate.setHours(0, 0, 0, 0);

            if (fechaUltimaActividad < inicioDate) {
                return false;
            }
        }

        // 7. Filtrar por fecha de fin
        if (options.fecha_fin) {
            const finDate = new Date(options.fecha_fin);
            // Establecer al final del día (23:59:59) en la zona horaria local
            finDate.setHours(23, 59, 59, 999);

            if (fechaUltimaActividad > finDate) {
                return false;
            }
        }

        return true;
    };

    private verificarLiquidadoEnMesActual(credito: Credito, options: FilterOptions): boolean {
        if (!credito.abonos || credito.abonos.length === 0) {
            return false;
        }

        // Obtener el último abono
        const ultimoAbono = credito.abonos.sort((a, b) =>
            new Date(b.fecha).getTime() - new Date(a.fecha).getTime()
        )[0];

        if (!ultimoAbono) {
            return false;
        }

        // Obtener la fecha del reporte del options
        const fechaReporte = options.fecha_fin ? new Date(options.fecha_fin) : new Date();

        // Comparar mes y año del último abono con el mes y año del reporte
        const fechaUltimoAbono = new Date(ultimoAbono.fecha);
        const mismoMes = fechaUltimoAbono.getMonth() === fechaReporte.getMonth();
        const mismoAnio = fechaUltimoAbono.getFullYear() === fechaReporte.getFullYear();

        return mismoMes && mismoAnio;
    }

    private calcularFechaUltimaActividad(credito: Credito, estadoCuenta: any): Date {
        // Si hay abonos distribuidos, usar la fecha del último abono
        const ultimoAbonoDistribuido = estadoCuenta.abonos_distribuidos?.at(-1)?.abono.fecha;
        if (ultimoAbonoDistribuido) {
            return new Date(ultimoAbonoDistribuido);
        }

        // Si hay abonos directos, usar la fecha del último abono
        if (credito.abonos && credito.abonos.length > 0) {
            const ultimoAbono = credito.abonos.sort((a, b) =>
                new Date(b.fecha).getTime() - new Date(a.fecha).getTime()
            )[0];
            if (ultimoAbono) {
                return new Date(ultimoAbono.fecha);
            }
        }

        // Si no hay pagos, usar la fecha de convenio
        return new Date(credito.fecha_convenio ?? credito.liberado_fecha ?? credito.formalizado_fecha ?? credito.created_at);
    }

    private verificarActividadReciente(fechaUltimaActividad: Date): boolean {
        const fechaActual = new Date();
        const fechaLimite = new Date(fechaActual.getFullYear() - 6, fechaActual.getMonth(), fechaActual.getDate());

        return fechaUltimaActividad >= fechaLimite;
    }
}