import { Injectable } from '@angular/core';
import { BuroSuperService } from './buro.super.service';

/**
 * Interfaz para el Segmento HD (Encabezado) del archivo de reporte a Buró de Crédito.
 * Este segmento es obligatorio y debe aparecer solo una vez al inicio del archivo.
 * Aplica para Personas Morales, PFAE, Fondos y Fideicomisos.
 *
 * Documentación: Manual Técnico Entrega BD PM_B.pdf (Septiembre 2024)
 */
export interface EncabezadoBuro {
    /**
     * HD: Identificador del segmento. Siempre debe ser 'BNCPM'.
     * Es el inicio del archivo. Si no es 'BNCPM', el archivo será rechazado.
     */
    identificadorSegmento: string; // 'HD'

    /**
     * 00 - CLAVE DEL USUARIO
     * Debe contener los 4 dígitos numéricos (CCCC) de tu clave de usuario asignada por Buró.
     * Ejemplo: Si tu clave es BU9014XYZ1 → reportar '9014'
     */
    claveUsuario: string; // 4 caracteres numéricos

    /**
     * 01 - CLAVE DEL USUARIO ANTERIOR
     * Actualmente deshabilitado. Debe reportarse como '0000'.
     */
    claveUsuarioAnterior: string; // '0000'

    /**
     * 02 - TIPO DE USUARIO
     * Código que identifica el tipo de institución.
     * Para Fideicomisos y Fondos: usar '008'.
     *
     * Valores clave:
     * 001 = Banco
     * 005 = Otras Financieras
     * 008 = Fondos y Fideicomisos  ← Este es tu caso
     * 010 = Fianzas
     * 999 = Comercial
     */
    tipoUsuario: string; // 3 caracteres, ej. '008'

    /**
     * 03 - TIPO DE FORMATO
     * 1 = Formato Detallado (Financiero) → Obligatorio para Fondos/Fideicomisos
     * 2 = Formato Sumarizado (Comercial)
     */
    tipoFormato: string; // '1' o '2' → usar '1'

    /**
     * 04 - FECHA DE REPORTE DE INFORMACIÓN
     * Fecha del último día del periodo reportado (corte).
     * Formato AAAAMMDD (ej: 20240930 para 30 de septiembre de 2024)
     */
    fechaReporte: string; // AAAAMMDD

    /**
     * 05 - PERIODO
     * Periodo contable que se está reportando.
     * Formato: MMAAAA (ej: 092024 para septiembre de 2024)
     */
    periodo: string; // MMAAAA

    /**
     * 06 - VERSIÓN
     * Siempre debe ser '05' (versión actual del formato).
     */
    version: string; // '05'

    /**
     * 07 - NOMBRE DEL OTORGANTE
     * Nombre corto de tu institución tal como está registrado en Buró de Crédito.
     * Requerido. Máximo 50 caracteres.
     */
    nombreOtorgante: string; // Ej: 'FIDEICOMISO TECNOLOGICO'

    /**
     * 08 - FILLER
     * Campo reservado para uso futuro.
     * Debe llenarse con exactamente 52 espacios en blanco.
     */
    filler: string; // 52 espacios
}

@Injectable({
    providedIn: 'any'
})

export class BuroEncabezadoService {

    /**
     * Convierte el encabezado del Buró a formato de string para el archivo
     * @param encabezado - Objeto con la información del encabezado
     * @returns String formateado según las especificaciones del Buró de Crédito
     */
    mapEncabezado(encabezado: EncabezadoBuro): string {
        let str =''
        str += 'HD' + this.format(encabezado.identificadorSegmento, 5)
        str += '00' + this.format(encabezado.claveUsuario, 4)
        str += '01' + this.format(encabezado.claveUsuarioAnterior, 4)
        str += '02' + this.format(encabezado.tipoUsuario, 3)
        str += '03' + this.format(encabezado.tipoFormato, 1)
        str += '04' + this.format(encabezado.fechaReporte, 8)
        str += '05' + this.format(encabezado.periodo, 6)
        str += '06' + this.format(encabezado.version, 2)
        str += '07' + this.format(encabezado.nombreOtorgante, 75)
        str += '08' + this.format(encabezado.filler, 52)
        return str;
    }

    protected format(value:string|null|undefined, len:number, number?:boolean){
        if(!value) return number? ''.padStart(len,'0') : ''.padEnd(len,' ')

        return number? value.padStart(len, '0') : value.padEnd(len, ' ').substring(0,len)
    }
}