import { Injectable } from '@angular/core';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { BehaviorSubject, firstValueFrom } from 'rxjs';
import { Credito } from '../../../models/credito.model';

@Injectable({
    providedIn: 'root'
})
export class ConsolidadoJuridicoService {
    endpoint = 'api/consolidado/juridico'
    data: Credito[] = []

    private progressSubject = new BehaviorSubject<number>(0);
    public progress$ = this.progressSubject.asObservable();

    constructor(
        private api: ApiServiceService,
    ) { }

    public async fetchData(options?: {
        inicio?: string;
        fin?: string;
        producto_financiero_id?: number | null;
    }) {
        if (!this.data.length) {
            await this.initData()
        }
        return this.data
            .filter(c => {
                if(!c.creditos_pagos?.length || !c.juridicos){
                    return false
                }
                if(!options){
                    return true
                }
                // 1. Filtrar por producto financiero
                if (options.producto_financiero_id && c.productos_financiero_id != options.producto_financiero_id) {
                    return false;
                }

                // 2. Si no hay fechas para filtrar, retorna true
                if (!options.inicio && !options.fin) {
                    return true;
                }

                return true;
            });
    }

    private async initData() {
        // Primero, obtener el número total de páginas
        const firstPage = await firstValueFrom(
            this.api.get<Credito[]>(this.endpoint, { page: 1, per_page: 500 }, false)
        );
        const lastPage = firstPage.total_pages ?? 0;

        // Generar todas las páginas
        const pages = Array.from({ length: lastPage }, (_, i) => i + 1);

        // Procesar en lotes de 5 páginas simultáneas
        const chunkSize = 5;
        let currentPage =1;
        for (let i = 0; i < pages.length; i += chunkSize) {
            const chunk = pages.slice(i, i + chunkSize);
            const promises = chunk.map(page =>
                firstValueFrom(this.api.get<Credito[]>(this.endpoint, { page, per_page: 500 }, false))
                    .then(res => { 
                        this.progressSubject.next((page/pages.length)*100)
                        currentPage++;
                        return res.data ?? []
                    })
            );

            const results = await Promise.all(promises);
            results.forEach(data => this.data.push(...data));
        }
    }
}
