import { Component } from '@angular/core';
import { AutocompleteFieldComponent } from "../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { FormsModule } from '@angular/forms';
import { SesionadosCreditosComponent } from "./sesionados-creditos/sesionados-creditos.component";
import { DatePipe } from '@angular/common';
import { SesionadosApoyosComponent } from "./sesionados-apoyos/sesionados-apoyos.component";

export interface SesionadosFiltros{
  sesion_id?:number;
  fecha_inicio?:number;
  fecha_fin?:number;
  programa_apoyo_id?:number;
  producto_financiero_id?:number;
}

@Component({
    selector: 'app-sesionados',
    imports: [
    AutocompleteFieldComponent,
    FormsModule,
    SesionadosCreditosComponent,
    SesionadosApoyosComponent,
    DatePipe
],
    templateUrl: './sesionados.component.html',
    styleUrl: './sesionados.component.css'
})

export class SesionadosComponent {
  today = new Date()
  filtros:SesionadosFiltros={}
  showResultados:boolean=false
  showCreditos=true

  constructor(
  ){}

  public buscar(){
    this.filtros={
      ...this.filtros,
    }
    this.showResultados = true;
  }

  public limpiarFiltros(){
    this.showResultados=false
    this.filtros={}
  }
}
