import { Injectable } from '@angular/core';
import { Credito } from '../../../../models/credito.model';

@Injectable({
    providedIn: 'any'
})
export class BuroUtilsService {

    formatDateToYYYYMMDD(date: string | Date | null | undefined): string {
        // Manejar valores nulos o undefined
        if (date === null || date === undefined) {
            return '';
        }

        // Convertir string a Date si es necesario
        const dateObj = typeof date === 'string' ? new Date(date) : date;

        // Validar que sea una fecha válida
        if (isNaN(dateObj.getTime())) {
            return '';
        }

        // Obtener componentes de la fecha
        const year = dateObj.getFullYear();
        const month = String(dateObj.getMonth() + 1).padStart(2, '0');
        const day = String(dateObj.getDate()).padStart(2, '0');

        // Formatear como YYYY-MM-DD
        return `${year}-${month}-${day}`;
    }


    formatDateToDDMMYYYY(date: string | Date | null | undefined): string {
        if (!date) {
            return '00000000';
        }

        let fecha: Date;

        try {
            // Convertimos si es string
            fecha = typeof date === 'string' ? new Date(date) : date;

            // Validamos que sea una fecha válida
            if (isNaN(fecha.getTime())) {
                return '00000000';
            }
        } catch {
            return '00000000';
        }

        const day = fecha.getDate();           // Día del mes (1-31)
        const month = fecha.getMonth() + 1;    // Mes (0-11 → 1-12)
        const year = fecha.getFullYear();      // Año (ej: 2024)

        // Formateamos: DDMMAAAA con ceros a la izquierda
        return (
            day.toString().padStart(2, '0') +
            month.toString().padStart(2, '0') +
            year.toString().padStart(4, '0')
        );
    }

    formatDomicilio(domicilio: {
        calle: string;
        no_exterior: string | null;
        no_interior: string | null;
    } | null | undefined): { linea1: string; linea2: string } {
        if (!domicilio) return { linea1: '', linea2: '' }
        if (!domicilio.calle || domicilio.calle.trim() === '') {
            return {
                linea1: 'DOMICILIO CONOCIDO SN'.padEnd(40, ' '),
                linea2: ' '.repeat(40)
            };
        }

        let direccion = domicilio.calle.trim();
        const numExt = domicilio.no_exterior?.trim();
        const numInt = domicilio.no_interior?.trim();

        if (!numExt) {
            direccion += ' SN';
        } else {
            direccion += ` ${numExt}`;
            if (numInt) {
                direccion += ` Int ${numInt}`;
            }
        }

        if (direccion.length <= 40) {
            return {
                linea1: direccion.padEnd(40, ' '),
                linea2: ' '.repeat(40)
            };
        }

        const linea1 = direccion.substring(0, 40);
        const sobrante = direccion.substring(40);
        const linea2 = sobrante.length > 0
            ? sobrante.substring(0, 40).padEnd(40, ' ')
            : ' '.repeat(40);

        return {
            linea1: linea1.padEnd(40, ' '),
            linea2: linea2
        };
    }

    esPersonaMoral(rfc: string | null | undefined): boolean | null {
        if (!rfc) {
            return null;
        }

        // l-limpiamos el rfc, por si tiene espacios o minúsculas
        const rfcLimpio = rfc.trim().toUpperCase();

        // v-validamos longitud: debe ser 12 (moral) o 13 (física)
        if (rfcLimpio.length === 12) {
            // s-si tiene 12 caracteres → es PERSONA MORAL (por definición)
            return true;
        } else if (rfcLimpio.length === 13) {
            // s-si tiene 13 → es PERSONA FÍSICA
            return false;
        } else {
            // s-si no es 12 ni 13… n-no es válido
            return null;
        }
    }

    separarNombreCompleto(nombreCompleto: string | null | undefined) {
        // Si no hay nombre, regresamos todo vacío
        if (!nombreCompleto || typeof nombreCompleto !== 'string') {
            return {
                nombre: '',
                nombre_adicional: '',
                apellido_paterno: '',
                apellido_materno: ''
            };
        }

        // Limpiamos y separamos por espacios
        const partes = nombreCompleto
            .trim()
            .replace(/\s+/g, ' ')
            .split(' ')
            .filter(p => p);

        if (partes.length === 0) {
            return {
                nombre: '',
                nombre_adicional: '',
                apellido_paterno: '',
                apellido_materno: ''
            };
        }

        let nombre = '';
        let nombre_adicional = '';
        let apellido_paterno = '';
        let apellido_materno = '';

        // Casos según cantidad de palabras
        if (partes.length === 1) {
            nombre = partes[0];
        } else if (partes.length === 2) {
            nombre = partes[0];
            apellido_paterno = partes[1];
        } else if (partes.length === 3) {
            nombre = partes[0];
            apellido_paterno = partes[1];
            apellido_materno = partes[2];
        } else if (partes.length === 4) {
            nombre = partes[0];
            nombre_adicional = partes[1];
            apellido_paterno = partes[2];
            apellido_materno = partes[3];
        } else {
            // 5 o más: asumimos que los últimos 2 son apellidos
            apellido_paterno = partes[partes.length - 2];
            apellido_materno = partes[partes.length - 1];
            // Los primeros son nombres
            nombre = partes[0];
            nombre_adicional = partes.slice(1, -2).join(' ');
        }

        return {
            nombre,
            nombre_adicional,
            apellido_paterno,
            apellido_materno
        };
    }

    folioCredito(credito: Credito): string {
        const convenios = credito.convenios?.filter(c => c.estatus !== 'CANCELADO') ?? []
        if (!convenios?.length) return credito.folio ?? '';

        return (credito.folio ?? '') + 'R'.repeat(convenios.length);
    }

    folioAnterior(credito: Credito) {
        const folio = this.folioCredito(credito)
        if (!folio.length) return ''
        if (folio[folio.length - 1] == 'R') {
            return folio.substring(0, folio.length - 1)
        }
        return ''
    }
}