import { Component, inject, OnInit } from '@angular/core';
import { COBRANZA_COLUMNS_CLUSTERS, InformeCobranzaService } from '../services/informe-cobranza.service';
import { InformeTablaDinamicaLocalComponent } from "../informe-tabla-dinamica-local/informe-tabla-dinamica-local.component";
import { ConsolidadoRow, FilterOptions } from '../services/consolidado.super.service';
import { ProgressBarConsolidadoComponent } from "../shared/progress-bar-consolidado/progress-bar-consolidado.component";
import { DatesPickerComponent } from "../shared/dates-picker/dates-picker.component";

@Component({
  selector: 'app-informe-cobranza',
  imports: [
    InformeTablaDinamicaLocalComponent,
    ProgressBarConsolidadoComponent,
    DatesPickerComponent
  ],
  templateUrl: './informe-cobranza.component.html',
  styleUrl: './informe-cobranza.component.css'
})
export class InformeCobranzaComponent implements OnInit {
  dataSource: ConsolidadoRow[] = []
  options: FilterOptions = {}
  columnsClusters = COBRANZA_COLUMNS_CLUSTERS
  progress = 0
  isLoading = false

  private informeCobranzaController = inject(InformeCobranzaService)

  ngOnInit() {
    this.informeCobranzaController.progress$.subscribe(p => {
      this.progress = p
    })
  }

  public async fetchData() {
    this.isLoading = true
    this.dataSource = await this.informeCobranzaController.fetchDataMaped(this.options)
    this.isLoading = false

    console.log(this.dataSource)
  }
}
